VALUES ('doc-09-mitre-attack-p0-8543', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT32](https://attack.mitre.org/groups/G0050) has used PubPrn.vbs within execution scripts to execute malware, possibly bypassing defenses.(Citation: Twitter ItsReallyNick Status Update APT32 PubPrn)", "external_references": [{"description": "Carr, N. (2017, December 22). ItsReallyNick Status Update. Retrieved September 12, 2024.", "source_name": "Twitter ItsReallyNick Status Update APT32 PubPrn", "url": "https://x.com/ItsReallyNick/status/944321013084573697"}], "id": "relationship--36f3f6df-5007-4075-84a3-9708132f1468", "modified": "2026-07-31T18:47:44.138Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--247cb30b-955f-42eb-97a5-a89fef69341e", "spec_version": "2.1", "target_ref": "attack-pattern--09cd431f-eaf4-4d2a-acaf-2a7acfe7ed58", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8543', 0, 71, '09-mitre-attack', 'retrieved', 'A6A71C8979B3C6B52E74BDD09AB19801828E5625EB87D1D60B6D82A52090F1CE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
