VALUES ('doc-09-mitre-attack-p0-8547', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-30T20:26:08.736Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "An [APT32](https://attack.mitre.org/groups/G0050) backdoor can use HTTP over a non-standard TCP port (e.g 14146) which is specified in the backdoor configuration.(Citation: ESET OceanLotus Mar 2019)", "external_references": [{"description": "Dumont, R. (2019, March 20). Fake or Fake: Keeping up with OceanLotus decoys. Retrieved April 1, 2019.", "source_name": "ESET OceanLotus Mar 2019", "url": "https://www.welivesecurity.com/2019/03/20/fake-or-fake-keeping-up-with-oceanlotus-decoys/"}], "id": "relationship--4050ee68-3f26-49e6-beec-e2a62133a1c3", "modified": "2026-07-31T18:47:44.232Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--247cb30b-955f-42eb-97a5-a89fef69341e", "spec_version": "2.1", "target_ref": "attack-pattern--b18eae87-b469-4e14-b454-b171b416bc18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8547', 0, 79, '09-mitre-attack', 'retrieved', '20E4A21B26C56207E8667C82C22EA1AF174F7CA849F2A94482147886D9E0EF82', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
