VALUES ('doc-09-mitre-attack-p0-8564', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-31T01:07:58.546Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT32](https://attack.mitre.org/groups/G0050) performed network scanning on the network to search for open ports, services, OS finger-printing, and other vulnerabilities.(Citation: Cybereason Cobalt Kitty 2017)", "external_references": [{"description": "Dahan, A. (2017). Operation Cobalt Kitty. Retrieved December 27, 2018.", "source_name": "Cybereason Cobalt Kitty 2017", "url": "https://cdn2.hubspot.net/hubfs/3354902/Cybereason%20Labs%20Analysis%20Operation%20Cobalt%20Kitty.pdf"}], "id": "relationship--63994c7c-6544-4e29-9c94-ac2237166774", "modified": "2026-07-31T18:47:44.598Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--247cb30b-955f-42eb-97a5-a89fef69341e", "spec_version": "2.1", "target_ref": "attack-pattern--e3a12395-188d-4051-9a16-ea8e14d07b88", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8564', 0, 70, '09-mitre-attack', 'retrieved', '9C0290BDC10F1E92B3746C51FB2DED850440ED833DA932909F5FFDBE4DBE009F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
