VALUES ('doc-09-mitre-attack-p0-8608', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-10T21:57:37.023Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT32](https://attack.mitre.org/groups/G0050) has used the WindowStyle parameter to conceal [PowerShell](https://attack.mitre.org/techniques/T1059/001) windows. (Citation: FireEye APT32 May 2017) (Citation: Cybereason Cobalt Kitty 2017)", "external_references": [{"description": "Carr, N.. (2017, May 14). Cyber Espionage is Alive and Well: APT32 and the Threat to Global Corporations. Retrieved June 18, 2017.", "source_name": "FireEye APT32 May 2017", "url": "https://www.fireeye.com/blog/threat-research/2017/05/cyber-espionage-apt32.html"}, {"description": "Dahan, A. (2017). Operation Cobalt Kitty. Retrieved December 27, 2018.", "source_name": "Cybereason Cobalt Kitty 2017", "url": "https://cdn2.hubspot.net/hubfs/3354902/Cybereason%20Labs%20Analysis%20Operation%20Cobalt%20Kitty.pdf"}], "id": "relationship--db8530c2-ce41-4943-8a17-91502187fd06", "modified": "2026-07-31T18:47:45.538Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--247cb30b-955f-42eb-97a5-a89fef69341e", "spec_version": "2.1", "target_ref": "attack-pattern--cbb66055-0325-4111-aca0-40547b6ad5b0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8608', 0, 98, '09-mitre-attack', 'retrieved', '28F2CCFDB7525EDFF722970AA39E811F0174651164586B71E7B17494C4E2C6DB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
