VALUES ('doc-09-mitre-attack-p0-8609', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT32](https://attack.mitre.org/groups/G0050) has performed code obfuscation, including encoding payloads using Base64 and using a framework called \"Dont-Kill-My-Cat (DKMC). [APT32](https://attack.mitre.org/groups/G0050) also encrypts the library used for network exfiltration with AES-256 in CBC mode in their macOS backdoor.(Citation: FireEye APT32 May 2017)(Citation: GitHub Invoke-Obfuscation)(Citation: ESET OceanLotus)(Citation: Cybereason Oceanlotus May 2017)(Citation: Cybereason Cobalt Kitty 2017)(Citation: ESET OceanLotus Mar 2019)(Citation: ESET OceanLotus macOS April 2019)", "external_references": [{"description": "Bohannon, D.. (2017, March 13). Invoke-Obfuscation - PowerShell Obfuscator. Retrieved June 18, 2017.", "source_name": "GitHub Invoke-Obfuscation", "url": "https://github.com/danielbohannon/Invoke-Obfuscation"}, {"description": "Carr, N.. (2017, May 14). Cyber Espionage is Alive and Well: APT32 and the Threat to Global Corporations. Retrieved June 18, 2017.", "source_name": "FireEye APT32 May 2017", "url": "https://www.fireeye.com/blog/threat-research/2017/05/cyber-espionage-apt32.html"}, {"description": "Dahan, A. (2017, May 24). OPERATION COBALT KITTY: A LARGE-SCALE APT IN ASIA CARRIED OUT BY THE OCEANLOTUS GROUP. Retrieved November 5, 2018.", "source_name": "Cybereason Oceanlotus May 2017", "url": "https://www.cybereason.com/blog/operation-cobalt-kitty-apt"}, {"description": "Dahan, A. (2017). Operation Cobalt Kitty. Retrieved December 27, 2018.", "source_name": "Cybereason Cobalt Kitty 2017", "url": "https://cdn2.hubspot.net/hubfs/3354902/Cybereason%20Labs%20Analysis%20Operation%20Cobalt%20Kitty.pdf"}, {"description": "Dumont, R. (2019, March 20). Fake or Fake: Keeping up with OceanLotus decoys. Retrieved April 1, 2019.", "source_name": "ESET OceanLotus Mar 2019", "url": "https://www.welivesecurity.com/2019/03/20/fake-or-fake-keeping-up-with-oceanlotus-decoys/"}, {"description": "Dumont, R.. (2019, April 9). OceanLotus: macOS malware update. Retrieved April 15, 2019.", "source_name": "ESET OceanLotus macOS April 2019", "url": "https://www.welivesecurity.com/2019/04/09/oceanlotus-macos-malware-update/"}, {"description": "Foltýn, T. (2018, March 13). OceanLotus ships new backdoor using old tricks. Retrieved May 22, 2018.", "source_name": "ESET OceanLotus", "url": "https://www.welivesecurity.com/2018/03/13/oceanlotus-ships-new-backdoor/"}], "id": "relationship--db91e39d-daa4-4f9c-a7a6-be67eba712d2", "modified": "2026-07-31T18:47:45.613Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--247cb30b-955f-42eb-97a5-a89fef69341e", "spec_version": "2.1", "target_ref": "attack-pattern--0d91b3c0-5e50-47c3-949a-2a796f04d144", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8609', 0, 257, '09-mitre-attack', 'retrieved', '3C99F16AEE20D62067FFB6311452060CB7C6DE79FBC4C8263CE8CE242636FA38', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
