VALUES ('doc-09-mitre-attack-p0-8679', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MuddyWater](https://attack.mitre.org/groups/G0069) has used mshta.exe to execute its [POWERSTATS](https://attack.mitre.org/software/S0223) payload and to pass a PowerShell one-liner for execution.(Citation: FireEye MuddyWater Mar 2018)(Citation: Securelist MuddyWater Oct 2018)", "external_references": [{"description": "Singh, S. et al.. (2018, March 13). Iranian Threat Group Updates Tactics, Techniques and Procedures in Spear Phishing Campaign. Retrieved April 11, 2018.", "source_name": "FireEye MuddyWater Mar 2018", "url": "https://www.fireeye.com/blog/threat-research/2018/03/iranian-threat-group-updates-ttps-in-spear-phishing-campaign.html"}, {"description": "Kaspersky Lab''s Global Research & Analysis Team. (2018, October 10). MuddyWater expands operations. Retrieved November 2, 2018.", "source_name": "Securelist MuddyWater Oct 2018", "url": "https://securelist.com/muddywater/88059/"}], "id": "relationship--1923bc58-a830-457d-810f-27091e032f46", "modified": "2026-07-31T20:48:29.644Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--269e8108-68c6-4f99-b911-14b2e765dec2", "spec_version": "2.1", "target_ref": "attack-pattern--840a987a-99bd-4a80-a5c9-0cb2baa6cade", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8679', 0, 111, '09-mitre-attack', 'retrieved', '430B00E6A0E890FD72660ED86DF4276870C00DF73F1E57632FE93C41A52FF097', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
