VALUES ('doc-09-mitre-attack-p0-8683', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-19T23:45:03.141Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MuddyWater](https://attack.mitre.org/groups/G0069) has performed credential dumping with [LaZagne](https://attack.mitre.org/software/S0349).(Citation: Unit 42 MuddyWater Nov 2017)(Citation: Symantec MuddyWater Dec 2018)", "external_references": [{"description": "Lancaster, T.. (2017, November 14). Muddying the Water: Targeted Attacks in the Middle East. Retrieved March 15, 2018.", "source_name": "Unit 42 MuddyWater Nov 2017", "url": "https://researchcenter.paloaltonetworks.com/2017/11/unit42-muddying-the-water-targeted-attacks-in-the-middle-east/"}, {"description": "Symantec DeepSight Adversary Intelligence Team. (2018, December 10). Seedworm: Group Compromises Government Agencies, Oil & Gas, NGOs, Telecoms, and IT Firms. Retrieved December 14, 2018.", "source_name": "Symantec MuddyWater Dec 2018", "url": "https://www.symantec.com/blogs/threat-intelligence/seedworm-espionage-group"}], "id": "relationship--1eb79c3a-2cee-48ff-80b1-a5c3f571a3e8", "modified": "2026-07-31T20:48:29.677Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--269e8108-68c6-4f99-b911-14b2e765dec2", "spec_version": "2.1", "target_ref": "attack-pattern--1ecfdab8-7d59-4c98-95d4-dc41970f57fc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8683', 0, 106, '09-mitre-attack', 'retrieved', 'C521C90E79CFB2C4113987ACCC78A71F7DA37034DF681423B5941EE60C764024', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
