VALUES ('doc-09-mitre-attack-p0-8715', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-30T17:33:40.973Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MuddyWater](https://attack.mitre.org/groups/G0069) has used malware that checked if the ProgramData folder had folders or files with the keywords \"Kasper,\" \"Panda,\" or \"ESET.\"(Citation: Securelist MuddyWater Oct 2018)", "external_references": [{"description": "Kaspersky Lab''s Global Research & Analysis Team. (2018, October 10). MuddyWater expands operations. Retrieved November 2, 2018.", "source_name": "Securelist MuddyWater Oct 2018", "url": "https://securelist.com/muddywater/88059/"}], "id": "relationship--7aab9015-1839-4672-9a9a-76f478c858a8", "modified": "2026-07-31T20:48:29.927Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--269e8108-68c6-4f99-b911-14b2e765dec2", "spec_version": "2.1", "target_ref": "attack-pattern--7bc57495-ea59-4380-be31-a64af124ef18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8715', 0, 80, '09-mitre-attack', 'retrieved', '0F39A127F3BDAFA6074153442AE26CDA08D40FAAA60B87D15981767DCCCF44EA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
