VALUES ('doc-09-mitre-attack-p0-8717', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-30T17:33:40.964Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MuddyWater](https://attack.mitre.org/groups/G0069) has used malware that can upload additional files to the victim’s machine.(Citation: Securelist MuddyWater Oct 2018)(Citation: ClearSky MuddyWater Nov 2018)(Citation: Reaqta MuddyWater November 2017)(Citation: Trend Micro Muddy Water March 2021) [MuddyWater](https://attack.mitre.org/groups/G0069) has used PowerShell commands to install remote management and monitoring (RMM) software on the victim’s machine to conduct espionage and to exfiltrate data.(Citation: NaumaanProofpoint_GlobalClickFix_April2025) ", "external_references": [{"description": "ClearSky Cyber Security. (2018, November). MuddyWater Operations in Lebanon and Oman: Using an Israeli compromised domain for a two-stage campaign. Retrieved November 29, 2018.", "source_name": "ClearSky MuddyWater Nov 2018", "url": "https://www.clearskysec.com/wp-content/uploads/2018/11/MuddyWater-Operations-in-Lebanon-and-Oman.pdf"}, {"description": "Kaspersky Lab''s Global Research & Analysis Team. (2018, October 10). MuddyWater expands operations. Retrieved November 2, 2018.", "source_name": "Securelist MuddyWater Oct 2018", "url": "https://securelist.com/muddywater/88059/"}, {"description": "Naumaan, S., et al. (2025, April 17). Around the World in 90 Days: State-Sponsored Actors Try ClickFix . Retrieved January 21, 2026.", "source_name": "NaumaanProofpoint_GlobalClickFix_April2025", "url": "https://www.proofpoint.com/us/blog/threat-insight/around-world-90-days-state-sponsored-actors-try-clickfix"}, {"description": "Peretz, A. and Theck, E. (2021, March 5). Earth Vetala – MuddyWater Continues to Target Organizations in the Middle East. Retrieved March 18, 2021.", "source_name": "Trend Micro Muddy Water March 2021", "url": "https://www.trendmicro.com/en_us/research/21/c/earth-vetala---muddywater-continues-to-target-organizations-in-t.html"}, {"description": "Reaqta. (2017, November 22). A dive into MuddyWater APT targeting Middle-East. Retrieved May 18, 2020.", "source_name": "Reaqta MuddyWater November 2017", "url": "https://reaqta.com/2017/11/muddywater-apt-targeting-middle-east/"}], "id": "relationship--82d8c106-c216-4d3f-9028-5f0b975e6330", "modified": "2026-07-31T20:48:29.943Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--269e8108-68c6-4f99-b911-14b2e765dec2", "spec_version": "2.1", "target_ref": "attack-pattern--e6919abc-99f9-4c6c-95a5-14761e7b2add", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8717', 0, 228, '09-mitre-attack', 'retrieved', '0068B799C025118B93CD5C2A281FE60E4F923AE29CAF3167BAAEBECD966BC5E5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
