VALUES ('doc-09-mitre-attack-p0-8745', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-18T19:04:37.692Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MuddyWater](https://attack.mitre.org/groups/G0069) has used scheduled tasks to establish persistence.(Citation: Reaqta MuddyWater November 2017)", "external_references": [{"description": "Reaqta. (2017, November 22). A dive into MuddyWater APT targeting Middle-East. Retrieved May 18, 2020.", "source_name": "Reaqta MuddyWater November 2017", "url": "https://reaqta.com/2017/11/muddywater-apt-targeting-middle-east/"}], "id": "relationship--c8f3916d-e020-42a8-afe0-25fe8498245a", "modified": "2026-07-31T20:48:30.170Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--269e8108-68c6-4f99-b911-14b2e765dec2", "spec_version": "2.1", "target_ref": "attack-pattern--005a06c6-14bf-4118-afa0-ebcd8aebb0c9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8745', 0, 65, '09-mitre-attack', 'retrieved', '8B77867B95D51DF09EAB4241D5B78C78AFB6CBC12BEBC5F8ED7F4B0B43171CEA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
