VALUES ('doc-09-mitre-attack-p0-8747', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-29T18:40:09.336Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "(Citation: CloudSEK_RustyWater_Jan2026)", "external_references": [{"description": "Awasthi, P. (2026, January 8). Reborn in Rust: Muddy Water Evolves Tooling with RustyWater Implant. Retrieved March 19, 2026.", "source_name": "CloudSEK_RustyWater_Jan2026", "url": "https://www.cloudsek.com/blog/reborn-in-rust-muddywater-evolves-tooling-with-rustywater-implant"}], "id": "relationship--cd19c1ef-38fc-45d7-ba6c-60773fce7890", "modified": "2026-07-31T20:48:30.185Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--269e8108-68c6-4f99-b911-14b2e765dec2", "spec_version": "2.1", "target_ref": "malware--50be4e81-db74-41a2-a9aa-423314082bea", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8747', 0, 56, '09-mitre-attack', 'retrieved', 'CCB5AC8128D87655B1F17CBCAB3FE54CE3A67C03C216490EA200CD8F818467A2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
