VALUES ('doc-09-mitre-attack-p0-8762', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:27.077Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Strider](https://attack.mitre.org/groups/G0041) has used local servers with both local network and Internet access to act as internal proxy nodes to exfiltrate data from other parts of the network without direct Internet access.(Citation: Kaspersky ProjectSauron Blog)", "external_references": [{"description": "Kaspersky Lab''s Global Research & Analysis Team. (2016, August 8). ProjectSauron: top level cyber-espionage platform covertly extracts encrypted government comms. Retrieved August 17, 2016.", "source_name": "Kaspersky ProjectSauron Blog", "url": "https://securelist.com/faq-the-projectsauron-apt/75533/"}], "id": "relationship--6476b9fe-dc7f-4578-a39d-beebc8390af2", "modified": "2026-07-31T18:47:45.467Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--277d2f87-2ae5-4730-a3aa-50c1fdff9656", "spec_version": "2.1", "target_ref": "attack-pattern--f6dacc85-b37d-458e-b58d-74fc4bbf5755", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8762', 0, 95, '09-mitre-attack', 'retrieved', '55441F2D02EEF93FE9BEF3285047689419EA5E00A79703F71C94998A2155A8D3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
