VALUES ('doc-09-mitre-attack-p0-8763', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:27.077Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Strider](https://attack.mitre.org/groups/G0041) has registered its persistence module on domain controllers as a Windows LSA (Local System Authority) password filter to acquire credentials any time a domain, local user, or administrator logs in or changes a password.(Citation: Kaspersky ProjectSauron Full Report)", "external_references": [{"description": "Kaspersky Lab''s Global Research & Analysis Team. (2016, August 9). The ProjectSauron APT. Retrieved August 17, 2016.", "source_name": "Kaspersky ProjectSauron Full Report", "url": "https://securelist.com/files/2016/07/The-ProjectSauron-APT_research_KL.pdf"}], "id": "relationship--8cbb1567-70c5-4daf-b163-cbc6cc40a794", "modified": "2026-07-31T18:47:45.504Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--277d2f87-2ae5-4730-a3aa-50c1fdff9656", "spec_version": "2.1", "target_ref": "attack-pattern--3731fbcd-0e43-47ae-ae6c-d15e510f0d42", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8763', 0, 94, '09-mitre-attack', 'retrieved', '0DF8F8667FE5757246D3D881A0C76818422314EC2FB2E9F2CD8B3DBE8E35D280', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
