VALUES ('doc-09-mitre-attack-p0-8834', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:27.071Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FIN6](https://attack.mitre.org/groups/G0037) used publicly available tools (including Microsoft''s built-in SQL querying tool, osql.exe) to map the internal network and conduct reconnaissance against Active Directory, Structured Query Language (SQL) servers, and NetBIOS.(Citation: FireEye FIN6 April 2016)", "external_references": [{"description": "FireEye Threat Intelligence. (2016, April). Follow the Money: Dissecting the Operations of the Cyber Crime Group FIN6. Retrieved November 17, 2024.", "source_name": "FireEye FIN6 April 2016", "url": "https://web.archive.org/web/20190807112824/https://www2.fireeye.com/rs/848-DID-242/images/rpt-fin6.pdf"}], "id": "relationship--b1c49faa-0b6f-4a0e-85da-5ab8ddeab2ce", "modified": "2026-07-31T20:48:31.039Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--2a7914cf-dff3-428d-ab0f-1014d1c28aeb", "spec_version": "2.1", "target_ref": "attack-pattern--e3a12395-188d-4051-9a16-ea8e14d07b88", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8834', 0, 93, '09-mitre-attack', 'retrieved', '9685F8A5CDAB148D2F07CECCAC10E9DD9D5629A8B7240D00034E10950C91B0EF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
