VALUES ('doc-09-mitre-attack-p0-8859', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-16T17:53:18.787Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gamaredon Group](https://attack.mitre.org/groups/G0047) macros can scan for Microsoft Word and Excel files to inject with additional malicious macros. [Gamaredon Group](https://attack.mitre.org/groups/G0047) has also used its backdoors to automatically list interesting files (such as Office documents) found on a system.(Citation: ESET Gamaredon June 2020)(Citation: Unit 42 Gamaredon February 2022)(Citation: ESET Gamaredon Sept2024) Gamaredon Group has also identified directory trees, folders and files on the compromised host.(Citation: SymantecCarbonBlack_ShuckwormUSB_Apr2025) ", "external_references": [{"description": "Boutin, J. (2020, June 11). Gamaredon group grows its game. Retrieved June 16, 2020.", "source_name": "ESET Gamaredon June 2020", "url": "https://www.welivesecurity.com/2020/06/11/gamaredon-group-grows-its-game/"}, {"description": "Rusnák, Z. (2024, September 26). Cyberespionage the Gamaredon way: Analysis of toolset used to spy on Ukraine in 2022 and 2023. Retrieved October 30, 2024.", "source_name": "ESET Gamaredon Sept2024", "url": "https://web-assets.esetstatic.com/wls/en/papers/white-papers/cyberespionage-gamaredon-way.pdf"}, {"description": "Threat Hunter Team, Symantec and Carbon Black. (2025, April 10). Shuckworm Targets Foreign Military Mission Based in Ukraine. Retrieved July 23, 2025.", "source_name": "SymantecCarbonBlack_ShuckwormUSB_Apr2025", "url": "https://www.security.com/threat-intelligence/shuckworm-ukraine-gammasteel"}, {"description": "Unit 42. (2022, February 3). Russia’s Gamaredon aka Primitive Bear APT Group Actively Targeting Ukraine. Retrieved February 21, 2022.", "source_name": "Unit 42 Gamaredon February 2022", "url": "https://unit42.paloaltonetworks.com/gamaredon-primitive-bear-ukraine-update-2021/"}], "id": "relationship--16b915ff-7bf5-4032-b39a-9c8073847d77", "modified": "2026-07-31T18:47:47.365Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--2e290bfe-93b5-48ce-97d6-edcd6d32b7cf", "spec_version": "2.1", "target_ref": "attack-pattern--7bc57495-ea59-4380-be31-a64af124ef18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8859', 0, 204, '09-mitre-attack', 'retrieved', '28FCC60F1FD2AED9FDD1CC32E54B7AA5A3BCB104A686A18A792CFEC509A6CFF7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
