VALUES ('doc-09-mitre-attack-p0-8862', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-02-21T15:38:23.557Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gamaredon Group](https://attack.mitre.org/groups/G0047) has used legitimate process names to hide malware including svchosst .(Citation: Unit 42 Gamaredon February 2022) Additionally, [Gamaredon Group](https://attack.mitre.org/groups/G0047) disguised malicious ZIP archives as Office documents that are related to the invasion.(Citation: VenereCiscoTalos_Gamaredon_Mar2025)", "external_references": [{"description": "Unit 42. (2022, February 3). Russia’s Gamaredon aka Primitive Bear APT Group Actively Targeting Ukraine. Retrieved February 21, 2022.", "source_name": "Unit 42 Gamaredon February 2022", "url": "https://unit42.paloaltonetworks.com/gamaredon-primitive-bear-ukraine-update-2021/"}, {"description": "Venere, G. (2025, March 28). Gamaredon campaign abuses LNK files to distribute Remcos backdoor. Retrieved July 23, 2025.", "source_name": "VenereCiscoTalos_Gamaredon_Mar2025", "url": "https://blog.talosintelligence.com/gamaredon-campaign-distribute-remcos/"}], "id": "relationship--1e049e66-14ce-46d5-8af1-d93ea35f4aec", "modified": "2026-07-31T18:47:47.406Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--2e290bfe-93b5-48ce-97d6-edcd6d32b7cf", "spec_version": "2.1", "target_ref": "attack-pattern--1c4e5d32-1fe9-4116-9d9d-59e3925bd6a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8862', 0, 116, '09-mitre-attack', 'retrieved', '4EAC14D12DDF5BD72AE720006EF7A06C138B59366D78E7C68A555D80DA55CCF9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_typ