VALUES ('doc-09-mitre-attack-p0-8871', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-19T20:39:12.457Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gamaredon Group](https://attack.mitre.org/groups/G0047) has embedded malicious macros in document templates, which executed VBScript. [Gamaredon Group](https://attack.mitre.org/groups/G0047) has also delivered Microsoft Outlook VBA projects with embedded macros.(Citation: TrendMicro Gamaredon April 2020)(Citation: ESET Gamaredon June 2020)(Citation: CERT-EE Gamaredon January 2021)(Citation: Microsoft Actinium February 2022)(Citation: Secureworks IRON TILDEN Profile)(Citation: ESET Gamaredon Sept2024) Additionally, [Gamaredon Group](https://attack.mitre.org/groups/G0047) has executed VBScript files using wscript.exe.(Citation: SymantecCarbonBlack_ShuckwormUSB_Apr2025) ", "external_references": [{"description": "Boutin, J. (2020, June 11). Gamaredon group grows its game. Retrieved June 16, 2020.", "source_name": "ESET Gamaredon June 2020", "url": "https://www.welivesecurity.com/2020/06/11/gamaredon-group-grows-its-game/"}, {"description": "CERT-EE. (2021, January 27). Gamaredon Infection: From Dropper to Entry. Retrieved February 17, 2022.", "source_name": "CERT-EE Gamaredon January 2021", "url": "https://www.ria.ee/sites/default/files/content-editors/kuberturve/tale_of_gamaredon_infection.pdf"}, {"description": "Kakara, H., Maruyama, E. (2020, April 17). Gamaredon APT Group Use Covid-19 Lure in Campaigns. Retrieved May 19, 2020.", "source_name": "TrendMicro Gamaredon April 2020", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/gamaredon-apt-group-use-covid-19-lure-in-campaigns/"}, {"description": "Microsoft Threat Intelligence Center. (2022, February 4). ACTINIUM targets Ukrainian organizations. Retrieved February 18, 2022.", "source_name": "Microsoft Actinium February 2022", "url": "https://www.microsoft.com/security/blog/2022/02/04/actinium-targets-ukrainian-organizations/"}, {"description": "Rusnák, Z. (2024, September 26). Cyberespionage the Gamaredon way: Analysis of toolset used to spy on Ukraine in 2022 and 2023. Retrieved October 30, 2024.", "source_name": "ESET Gamaredon Sept2024", "url": "https://web-assets.esetstatic.com/wls/en/papers/white-papers/cyberespionage-gamaredon-way.pdf"}, {"description": "Secureworks CTU. (n.d.). IRON TILDEN. Retrieved February 24, 2022.", "source_name": "Secureworks IRON TILDEN Profile", "url": "https://www.secureworks.com/research/threat-profiles/iron-tilden"}, {"description": "Threat Hunter Team, Symantec and Carbon Black. (2025, April 10). Shuckworm Targets Foreign Military Mission Based in Ukraine. Retrieved July 23, 2025.", "source_name": "SymantecCarbonBlack_ShuckwormUSB_Apr2025", "url": "https://www.security.com/threat-intelligence/shuckworm-ukraine-gammasteel"}], "id": "relationship--3a6022ea-7647-4d61-8103-dd354d8dfd4d", "modified": "2026-07-31T18:47:47.537Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--2e290bfe-93b5-48ce-97d6-edcd6d32b7cf", "spec_version": "2.1", "target_ref": "attack-pattern--dfd7cc1d-e1d8-4394-a198-97c4cab8aa67", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8871', 0, 258, '09-mitre-attack', 'retrieved', 'B6FF594600E44F2AF7B70C21BD9B6CFF7B1609243DD8B518BAD527638CFEBA90', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
