VALUES ('doc-09-mitre-attack-p0-8879', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-23T20:41:09.663Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gamaredon Group](https://attack.mitre.org/groups/G0047) has used Telegram Messenger content to discover the IP address for C2 communications.(Citation: unit42_gamaredon_dec2022)", "external_references": [{"description": "Unit 42. (2022, December 20). Russia’s Trident Ursa (aka Gamaredon APT) Cyber Conflict Operations Unwavering Since Invasion of Ukraine. Retrieved September 12, 2024.", "source_name": "unit42_gamaredon_dec2022", "url": "https://unit42.paloaltonetworks.com/trident-ursa/"}], "id": "relationship--524d0765-bef8-4146-b218-aa8a20719348", "modified": "2026-07-31T18:47:47.670Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--2e290bfe-93b5-48ce-97d6-edcd6d32b7cf", "spec_version": "2.1", "target_ref": "attack-pattern--9c99724c-a483-4d60-ad9d-7f004e42e8e8", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8879', 0, 74, '09-mitre-attack', 'retrieved', '902E2FEB902E0AFE0021ACADF122DD38A5767E44A76B2B56B373D613B64D31C2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
