VALUES ('doc-09-mitre-attack-p0-8881', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-15T13:50:12.466Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gamaredon Group](https://attack.mitre.org/groups/G0047) has tested connectivity between a compromised machine and a C2 server using [Ping](https://attack.mitre.org/software/S0097) with commands such as `CSIDL_SYSTEM\\cmd.exe /c ping -n 1`.(Citation: Symantec Shuckworm January 2022) [Gamaredon Group](https://attack.mitre.org/groups/G0047) has searched the ping records to obtain the C2 address and has used ping to search for the C2’s status.(Citation: SymantecCarbonBlack_ShuckwormUSB_Apr2025) ", "external_references": [{"description": "Symantec. (2022, January 31). Shuckworm Continues Cyber-Espionage Attacks Against Ukraine. Retrieved February 17, 2022.", "source_name": "Symantec Shuckworm January 2022", "url": "https://symantec-enterprise-blogs.security.com/blogs/threat-intelligence/shuckworm-gamaredon-espionage-ukraine"}, {"description": "Threat Hunter Team, Symantec and Carbon Black. (2025, April 10). Shuckworm Targets Foreign Military Mission Based in Ukraine. Retrieved July 23, 2025.", "source_name": "SymantecCarbonBlack_ShuckwormUSB_Apr2025", "url": "https://www.security.com/threat-intelligence/shuckworm-ukraine-gammasteel"}], "id": "relationship--5fc69974-db3b-4475-b37b-07c4731b1a6f", "modified": "2026-07-31T18:47:47.702Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--2e290bfe-93b5-48ce-97d6-edcd6d32b7cf", "spec_version": "2.1", "target_ref": "attack-pattern--132d5b37-aac5-4378-a8dc-3127b18a73dc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8881', 0, 131, '09-mitre-attack', 'retrieved', '9A247B8FA386D7E7A71E1F9D9FD8DFA2B216B6F72177C783CA713314F2D73028', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
