VALUES ('doc-09-mitre-attack-p0-8886', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-08-21T20:19:00.267Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gamaredon Group](https://attack.mitre.org/groups/G0047) used [Remcos](https://attack.mitre.org/software/S0332) during operations.(Citation: VenereCiscoTalos_Gamaredon_Mar2025)", "external_references": [{"description": "Venere, G. (2025, March 28). Gamaredon campaign abuses LNK files to distribute Remcos backdoor. Retrieved July 23, 2025.", "source_name": "VenereCiscoTalos_Gamaredon_Mar2025", "url": "https://blog.talosintelligence.com/gamaredon-campaign-distribute-remcos/"}], "id": "relationship--7c7b3761-80ff-4469-ad5b-9cc9a26078db", "modified": "2026-07-31T18:47:47.775Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--2e290bfe-93b5-48ce-97d6-edcd6d32b7cf", "spec_version": "2.1", "target_ref": "tool--7cd0bc75-055b-4098-a00e-83dc8beaff14", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8886', 0, 60, '09-mitre-attack', 'retrieved', '80BC8B3567024ACED3AB8DA79C1AE786EC33D91962AEC39B4DCAF2422961704D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
