VALUES ('doc-09-mitre-attack-p0-8889', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-19T20:39:12.455Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gamaredon Group](https://attack.mitre.org/groups/G0047) tools decrypted additional payloads from the C2. [Gamaredon Group](https://attack.mitre.org/groups/G0047) has also decoded Base64-encoded source code of a downloader.(Citation: TrendMicro Gamaredon April 2020)(Citation: ESET Gamaredon June 2020)(Citation: ESET Gamaredon Sept2024) Additionally, [Gamaredon Group](https://attack.mitre.org/groups/G0047) has decoded Telegram content to reveal the IP address for C2 communications.(Citation: unit42_gamaredon_dec2022)", "external_references": [{"description": "Boutin, J. (2020, June 11). Gamaredon group grows its game. Retrieved June 16, 2020.", "source_name": "ESET Gamaredon June 2020", "url": "https://www.welivesecurity.com/2020/06/11/gamaredon-group-grows-its-game/"}, {"description": "Kakara, H., Maruyama, E. (2020, April 17). Gamaredon APT Group Use Covid-19 Lure in Campaigns. Retrieved May 19, 2020.", "source_name": "TrendMicro Gamaredon April 2020", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/gamaredon-apt-group-use-covid-19-lure-in-campaigns/"}, {"description": "Rusnák, Z. (2024, September 26). Cyberespionage the Gamaredon way: Analysis of toolset used to spy on Ukraine in 2022 and 2023. Retrieved October 30, 2024.", "source_name": "ESET Gamaredon Sept2024", "url": "https://web-assets.esetstatic.com/wls/en/papers/white-papers/cyberespionage-gamaredon-way.pdf"}, {"description": "Unit 42. (2022, December 20). Russia’s Trident Ursa (aka Gamaredon APT) Cyber Conflict Operations Unwavering Since Invasion of Ukraine. Retrieved September 12, 2024.", "source_name": "unit42_gamaredon_dec2022", "url": "https://unit42.paloaltonetworks.com/trident-ursa/"}], "id": "relationship--86bcc5c3-456e-4bac-a419-54f54af80325", "modified": "2026-07-31T18:47:47.811Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--2e290bfe-93b5-48ce-97d6-edcd6d32b7cf", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8889', 0, 186, '09-mitre-attack', 'retrieved', '73888DE0EA1F6FB5BA462C2CBC44131657FE9598577DC6B8409CB0FE565D6937', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
