VALUES ('doc-09-mitre-attack-p0-8900', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-02-18T15:13:56.312Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gamaredon Group](https://attack.mitre.org/groups/G0047) has used obfuscated PowerShell scripts for staging.(Citation: Microsoft Actinium February 2022)(Citation: ESET Gamaredon Sept2024) Additionally, (LinkById : G0047) has used PowerShell based tools later in its attack chain.(Citation: SymantecCarbonBlack_ShuckwormUSB_Apr2025) Additionally, [Gamaredon Group](https://attack.mitre.org/groups/G0047) has used the PowerShell cmdlet `Get-Command` to download and execute the next stage payload.(Citation: VenereCiscoTalos_Gamaredon_Mar2025) ", "external_references": [{"description": "Microsoft Threat Intelligence Center. (2022, February 4). ACTINIUM targets Ukrainian organizations. Retrieved February 18, 2022.", "source_name": "Microsoft Actinium February 2022", "url": "https://www.microsoft.com/security/blog/2022/02/04/actinium-targets-ukrainian-organizations/"}, {"description": "Rusnák, Z. (2024, September 26). Cyberespionage the Gamaredon way: Analysis of toolset used to spy on Ukraine in 2022 and 2023. Retrieved October 30, 2024.", "source_name": "ESET Gamaredon Sept2024", "url": "https://web-assets.esetstatic.com/wls/en/papers/white-papers/cyberespionage-gamaredon-way.pdf"}, {"description": "Threat Hunter Team, Symantec and Carbon Black. (2025, April 10). Shuckworm Targets Foreign Military Mission Based in Ukraine. Retrieved July 23, 2025.", "source_name": "SymantecCarbonBlack_ShuckwormUSB_Apr2025", "url": "https://www.security.com/threat-intelligence/shuckworm-ukraine-gammasteel"}, {"description": "Venere, G. (2025, March 28). Gamaredon campaign abuses LNK files to distribute Remcos backdoor. Retrieved July 23, 2025.", "source_name": "VenereCiscoTalos_Gamaredon_Mar2025", "url": "https://blog.talosintelligence.com/gamaredon-campaign-distribute-remcos/"}], "id": "relationship--c14a954c-5d6d-4f29-8542-934e0fa5e9d3", "modified": "2026-07-31T18:47:47.947Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--2e290bfe-93b5-48ce-97d6-edcd6d32b7cf", "spec_version": "2.1", "target_ref": "attack-pattern--970a3432-3237-47ad-bcca-7d8cbb217736", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8900', 0, 185, '09-mitre-attack', 'retrieved', 'EE706DD531390233C2A9CEE38372A5410C81F23AB3727BAB7B50E2E0E2C0E0D5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
