VALUES ('doc-09-mitre-attack-p0-8922', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-23T20:38:19.956Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gamaredon Group](https://attack.mitre.org/groups/G0047) has used geoblocking to limit downloads of the malicious file to specific geographic locations.(Citation: unit42_gamaredon_dec2022)(Citation: VenereCiscoTalos_Gamaredon_Mar2025)", "external_references": [{"description": "Unit 42. (2022, December 20). Russia’s Trident Ursa (aka Gamaredon APT) Cyber Conflict Operations Unwavering Since Invasion of Ukraine. Retrieved September 12, 2024.", "source_name": "unit42_gamaredon_dec2022", "url": "https://unit42.paloaltonetworks.com/trident-ursa/"}, {"description": "Venere, G. (2025, March 28). Gamaredon campaign abuses LNK files to distribute Remcos backdoor. Retrieved July 23, 2025.", "source_name": "VenereCiscoTalos_Gamaredon_Mar2025", "url": "https://blog.talosintelligence.com/gamaredon-campaign-distribute-remcos/"}], "id": "relationship--f523a64f-7c27-4c23-a35d-c56b4bcce8be", "modified": "2026-07-31T18:47:48.193Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--2e290bfe-93b5-48ce-97d6-edcd6d32b7cf", "spec_version": "2.1", "target_ref": "attack-pattern--853c4192-4311-43e1-bfbb-b11b14911852", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8922', 0, 99, '09-mitre-attack', 'retrieved', '24EC48546A6A40FEEB752539DD872D32A1E5B4DA9A0182A80129A83C7356820A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
