VALUES ('doc-09-mitre-attack-p0-8923', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-08-25T14:29:32.341Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gamaredon Group](https://attack.mitre.org/groups/G0047) has used several ways to try to resolve the C2 server, including: public third-party websites, an adversary-operated Telegraph channel, the [ngrok](https://attack.mitre.org/software/S0508) utility and the TXT record of a hardcoded C2 domain.(Citation: ESET Gamaredon Sept2024)(Citation: SymantecCarbonBlack_ShuckwormUSB_Apr2025)", "external_references": [{"description": "Rusnák, Z. (2024, September 26). Cyberespionage the Gamaredon way: Analysis of toolset used to spy on Ukraine in 2022 and 2023. Retrieved October 30, 2024.", "source_name": "ESET Gamaredon Sept2024", "url": "https://web-assets.esetstatic.com/wls/en/papers/white-papers/cyberespionage-gamaredon-way.pdf"}, {"description": "Threat Hunter Team, Symantec and Carbon Black. (2025, April 10). Shuckworm Targets Foreign Military Mission Based in Ukraine. Retrieved July 23, 2025.", "source_name": "SymantecCarbonBlack_ShuckwormUSB_Apr2025", "url": "https://www.security.com/threat-intelligence/shuckworm-ukraine-gammasteel"}], "id": "relationship--f62632c0-cddf-40ba-bba0-647b5c523606", "modified": "2026-07-31T18:47:48.200Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--2e290bfe-93b5-48ce-97d6-edcd6d32b7cf", "spec_version": "2.1", "target_ref": "attack-pattern--be055942-6e63-49d7-9fa1-9cb7d8a8f3f4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8923', 0, 126, '09-mitre-attack', 'retrieved', '76B904E4E0B41ED58A70C1D9FBAE2F8D286F679D1F22350B2BFAF8F06FE99F03', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
