VALUES ('doc-09-mitre-attack-p0-8927', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-16T17:53:18.771Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gamaredon Group](https://attack.mitre.org/groups/G0047) has used GitHub repositories for downloaders which will be obtained by the group''s .NET executable on the compromised system.(Citation: ESET Gamaredon June 2020)\t", "external_references": [{"description": "Boutin, J. (2020, June 11). Gamaredon group grows its game. Retrieved June 16, 2020.", "source_name": "ESET Gamaredon June 2020", "url": "https://www.welivesecurity.com/2020/06/11/gamaredon-group-grows-its-game/"}], "id": "relationship--fa7887c3-d49d-4499-9ee4-f9a504ce7dec", "modified": "2026-07-31T18:47:48.230Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--2e290bfe-93b5-48ce-97d6-edcd6d32b7cf", "spec_version": "2.1", "target_ref": "attack-pattern--830c9528-df21-472c-8c14-a036bf17d665", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8927', 0, 77, '09-mitre-attack', 'retrieved', '86B42F976A3C77B224AA8491B46F4553362A69C1E132E2650C056AD2CE0A7713', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
