VALUES ('doc-09-mitre-attack-p0-8937', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-14T12:54:39.489Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Storm-1811](https://attack.mitre.org/groups/G1046) is associated with the deployment of [Black Basta](https://attack.mitre.org/software/S1070) ransomware.(Citation: Microsoft Storm-1811 2024)(Citation: rapid7-email-bombing)", "external_references": [{"description": "Microsoft Threat Intelligence. (2024, May 15). Threat actors misusing Quick Assist in social engineering attacks leading to ransomware. Retrieved March 14, 2025.", "source_name": "Microsoft Storm-1811 2024", "url": "https://www.microsoft.com/en-us/security/blog/2024/05/15/threat-actors-misusing-quick-assist-in-social-engineering-attacks-leading-to-ransomware/"}, {"description": "Tyler McGraw, Thomas Elkins, and Evan McCann. (2024, May 10). Ongoing Social Engineering Campaign Linked to Black Basta Ransomware Operators. Retrieved January 31, 2025.", "source_name": "rapid7-email-bombing", "url": "https://www.rapid7.com/blog/post/2024/05/10/ongoing-social-engineering-campaign-linked-to-black-basta-ransomware-operators"}], "id": "relationship--035faa39-bed9-4aed-bbc4-80c7a653f046", "modified": "2026-07-31T18:47:47.710Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--319fd652-edde-46b2-9987-3519493989f5", "spec_version": "2.1", "target_ref": "malware--8d242fb4-9033-4f13-8a88-4b9b4bcd9a53", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8937', 0, 102, '09-mitre-attack', 'retrieved', '9CEF1DC92FC11D9C1C86B2E38E040CBDA245E7FEEA402B886917B07DBA8D59EF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowle