VALUES ('doc-09-mitre-attack-p0-8940', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-14T13:22:29.210Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Storm-1811](https://attack.mitre.org/groups/G1046) has deployed large volumes of non-malicious email spam to victims in order to prompt follow-on interactions with the threat actor posing as IT support or helpdesk to resolve the problem.(Citation: rapid7-email-bombing)(Citation: RedCanary Storm-1811 2024)", "external_references": [{"description": "Red Canary Intelligence. (2024, December 2). Storm-1811 exploits RMM tools to drop Black Basta ransomware. Retrieved March 14, 2025.", "source_name": "RedCanary Storm-1811 2024", "url": "https://redcanary.com/blog/threat-intelligence/storm-1811-black-basta/"}, {"description": "Tyler McGraw, Thomas Elkins, and Evan McCann. (2024, May 10). Ongoing Social Engineering Campaign Linked to Black Basta Ransomware Operators. Retrieved January 31, 2025.", "source_name": "rapid7-email-bombing", "url": "https://www.rapid7.com/blog/post/2024/05/10/ongoing-social-engineering-campaign-linked-to-black-basta-ransomware-operators"}], "id": "relationship--0596eecc-c6cd-4ec4-ac7a-9b0648e1a10f", "modified": "2026-07-31T18:47:47.756Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--319fd652-edde-46b2-9987-3519493989f5", "spec_version": "2.1", "target_ref": "attack-pattern--bed81616-3dde-4685-be6e-ba9820f9a7ed", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8940', 0, 120, '09-mitre-attack', 'retrieved', '37A0A2C05F2F65F378C2EBE627D88F404B86BDB6667F3F746E33838D07EB9D4B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_typ