VALUES ('doc-09-mitre-attack-p0-8954', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-14T13:34:10.666Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Storm-1811](https://attack.mitre.org/groups/G1046) has used a PowerShell script to capture user credentials after prompting a user to authenticate to run a malicious script masquerading as a legitimate update item.(Citation: rapid7-email-bombing)", "external_references": [{"description": "Tyler McGraw, Thomas Elkins, and Evan McCann. (2024, May 10). Ongoing Social Engineering Campaign Linked to Black Basta Ransomware Operators. Retrieved January 31, 2025.", "source_name": "rapid7-email-bombing", "url": "https://www.rapid7.com/blog/post/2024/05/10/ongoing-social-engineering-campaign-linked-to-black-basta-ransomware-operators"}], "id": "relationship--58c773e3-a31b-4562-83a5-815cf958b6be", "modified": "2026-07-31T18:47:47.923Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--319fd652-edde-46b2-9987-3519493989f5", "spec_version": "2.1", "target_ref": "attack-pattern--bb5a00de-e086-4859-a231-fa793f6797e2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8954', 0, 87, '09-mitre-attack', 'retrieved', 'B139F486C30827DA7A51CB7BD28A89242CFF6C712463B949E0480687974AD119', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
