VALUES ('doc-09-mitre-attack-p0-8955', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-14T13:56:21.794Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Storm-1811](https://attack.mitre.org/groups/G1046) has deployed a malicious DLL (7z.DLL) that is sideloaded by a modified, legitimate installer (7zG.exe) when that installer is executed with an additional command line parameter of `b` at runtime to load a [Cobalt Strike](https://attack.mitre.org/software/S0154) beacon payload.(Citation: rapid7-email-bombing)", "external_references": [{"description": "Tyler McGraw, Thomas Elkins, and Evan McCann. (2024, May 10). Ongoing Social Engineering Campaign Linked to Black Basta Ransomware Operators. Retrieved January 31, 2025.", "source_name": "rapid7-email-bombing", "url": "https://www.rapid7.com/blog/post/2024/05/10/ongoing-social-engineering-campaign-linked-to-black-basta-ransomware-operators"}], "id": "relationship--5a63e7cf-1914-4f05-ac85-5aa1690ed3ef", "modified": "2026-07-31T18:47:47.935Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--319fd652-edde-46b2-9987-3519493989f5", "spec_version": "2.1", "target_ref": "attack-pattern--2fee9321-3e71-4cf4-af24-d4d40d355b34", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8955', 0, 98, '09-mitre-attack', 'retrieved', 'A3BBA933C94DB8D9E13CDDBBED238DE14789C252D92C84CA0476BA403373DCEA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
