VALUES ('doc-09-mitre-attack-p0-8962', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-14T12:55:56.700Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Storm-1811](https://attack.mitre.org/groups/G1046) has used scripted `cURL` commands, [BITSAdmin](https://attack.mitre.org/software/S0190), and other mechanisms to retrieve follow-on batch scripts and tools for execution on victim devices.(Citation: Microsoft Storm-1811 2024)(Citation: rapid7-email-bombing)(Citation: RedCanary June Insights 2024)", "external_references": [{"description": "Microsoft Threat Intelligence. (2024, May 15). Threat actors misusing Quick Assist in social engineering attacks leading to ransomware. Retrieved March 14, 2025.", "source_name": "Microsoft Storm-1811 2024", "url": "https://www.microsoft.com/en-us/security/blog/2024/05/15/threat-actors-misusing-quick-assist-in-social-engineering-attacks-leading-to-ransomware/"}, {"description": "The Red Canary Team. (2024, June 20). Intelligence Insights: June 2024. Retrieved March 14, 2025.", "source_name": "RedCanary June Insights 2024", "url": "https://redcanary.com/blog/threat-intelligence/intelligence-insights-june-2024/"}, {"description": "Tyler McGraw, Thomas Elkins, and Evan McCann. (2024, May 10). Ongoing Social Engineering Campaign Linked to Black Basta Ransomware Operators. Retrieved January 31, 2025.", "source_name": "rapid7-email-bombing", "url": "https://www.rapid7.com/blog/post/2024/05/10/ongoing-social-engineering-campaign-linked-to-black-basta-ransomware-operators"}], "id": "relationship--8f025145-ed37-4a29-bf4c-2fb3aa42e1f1", "modified": "2026-07-31T18:47:48.015Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--319fd652-edde-46b2-9987-3519493989f5", "spec_version": "2.1", "target_ref": "attack-pattern--e6919abc-99f9-4c6c-95a5-14761e7b2add", "type": "relationship"