VALUES ('doc-09-mitre-attack-p0-8998', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-01T01:57:31.880Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TeamTNT](https://attack.mitre.org/groups/G0139) has used open-source tools such as Weave Scope to target exposed Docker API ports and gain initial access to victim environments.(Citation: Intezer TeamTNT September 2020)(Citation: Cisco Talos Intelligence Group) [TeamTNT](https://attack.mitre.org/groups/G0139) has also targeted exposed kubelets for Kubernetes environments.(Citation: Unit 42 Hildegard Malware)", "external_references": [{"description": "Chen, J. et al. (2021, February 3). Hildegard: New TeamTNT Cryptojacking Malware Targeting Kubernetes. Retrieved April 5, 2021.", "source_name": "Unit 42 Hildegard Malware", "url": "https://unit42.paloaltonetworks.com/hildegard-malware-teamtnt/"}, {"description": "Darin Smith. (2022, April 21). TeamTNT targeting AWS, Alibaba. Retrieved August 4, 2022.", "source_name": "Cisco Talos Intelligence Group", "url": "https://blog.talosintelligence.com/teamtnt-targeting-aws-alibaba-2/"}, {"description": "Fishbein, N. (2020, September 8). Attackers Abusing Legitimate Cloud Monitoring Tools to Conduct Cyber Attacks. Retrieved September 22, 2021.", "source_name": "Intezer TeamTNT September 2020", "url": "https://www.intezer.com/blog/cloud-security/attackers-abusing-legitimate-cloud-monitoring-tools-to-conduct-cyber-attacks/"}], "id": "relationship--01bebfd2-6c8c-4671-8754-34ca03c44299", "modified": "2026-07-31T18:47:48.897Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--35d1b3be-49d4-42f1-aaa6-ef159c880bca", "spec_version": "2.1", "target_ref": "attack-pattern--10d51417-ee35-4589-b1ff-b6df1c334e8d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_