VALUES ('doc-09-mitre-attack-p0-9002', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-01T01:57:31.776Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TeamTNT](https://attack.mitre.org/groups/G0139) has modified the permissions on binaries with chattr .(Citation: Trend Micro TeamTNT)(Citation: Cisco Talos Intelligence Group)", "external_references": [{"description": "Darin Smith. (2022, April 21). TeamTNT targeting AWS, Alibaba. Retrieved August 4, 2022.", "source_name": "Cisco Talos Intelligence Group", "url": "https://blog.talosintelligence.com/teamtnt-targeting-aws-alibaba-2/"}, {"description": "Fiser, D. Oliveira, A. (n.d.). Tracking the Activities of TeamTNT A Closer Look at a Cloud-Focused Malicious Actor Group. Retrieved September 22, 2021.", "source_name": "Trend Micro TeamTNT", "url": "https://documents.trendmicro.com/assets/white_papers/wp-tracking-the-activities-of-teamTNT.pdf"}], "id": "relationship--08c69567-a511-4a07-ab5d-a5bf77594129", "modified": "2026-07-31T18:47:49.002Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--35d1b3be-49d4-42f1-aaa6-ef159c880bca", "spec_version": "2.1", "target_ref": "attack-pattern--09b130a2-a77e-4af0-a361-f46f9aad1345", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9002', 0, 98, '09-mitre-attack', 'retrieved', '6894EDEB8779836805C82CE02EF8BA5AF179C8361D5C653CEAE3110F871B3024', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
