VALUES ('doc-09-mitre-attack-p0-9003', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-01T01:57:31.612Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TeamTNT](https://attack.mitre.org/groups/G0139) has used a payload that removes itself after running. [TeamTNT](https://attack.mitre.org/groups/G0139) also has deleted locally staged files for collecting credentials or scan results for local IP addresses after exfiltrating them.(Citation: ATT TeamTNT Chimaera September 2020)(Citation: Cisco Talos Intelligence Group)", "external_references": [{"description": "AT&T Alien Labs. (2021, September 8). TeamTNT with new campaign aka Chimaera. Retrieved September 22, 2021.", "source_name": "ATT TeamTNT Chimaera September 2020", "url": "https://cybersecurity.att.com/blogs/labs-research/teamtnt-with-new-campaign-aka-chimaera"}, {"description": "Darin Smith. (2022, April 21). TeamTNT targeting AWS, Alibaba. Retrieved August 4, 2022.", "source_name": "Cisco Talos Intelligence Group", "url": "https://blog.talosintelligence.com/teamtnt-targeting-aws-alibaba-2/"}], "id": "relationship--0b46eb26-ebc0-4fa7-8925-9b775571f793", "modified": "2026-07-31T18:47:49.026Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--35d1b3be-49d4-42f1-aaa6-ef159c880bca", "spec_version": "2.1", "target_ref": "attack-pattern--d63a3fb8-9452-4e9d-a60a-54be68d5998c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9003', 0, 115, '09-mitre-attack', 'retrieved', '0F448BFD8EE75CA9B5FC8754390F29E07BEAC51B3978E57CAC69BD283783CE4A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
