VALUES ('doc-09-mitre-attack-p0-9049', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-13T21:10:40.799Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TeamTNT](https://attack.mitre.org/groups/G0139) has leveraged AWS CLI to enumerate cloud environments with compromised credentials.(Citation: Talos TeamTNT)", "external_references": [{"description": "Darin Smith. (2022, April 21). TeamTNT targeting AWS, Alibaba. Retrieved July 8, 2022.", "source_name": "Talos TeamTNT", "url": "https://blog.talosintelligence.com/2022/04/teamtnt-targeting-aws-alibaba.html"}], "id": "relationship--da4059ab-c858-4df1-94e0-25db2d6ea136", "modified": "2026-07-31T18:47:50.113Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--35d1b3be-49d4-42f1-aaa6-ef159c880bca", "spec_version": "2.1", "target_ref": "attack-pattern--55bb4471-ff1f-43b4-88c1-c9384ec47abf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9049', 0, 63, '09-mitre-attack', 'retrieved', 'A45EB83C1E7EBEB8CBBE051C8C0CB4B22AB3F7E840F1A266E84E394BAAB19DB1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
