VALUES ('doc-09-mitre-attack-p0-9074', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-22T13:52:51.063Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FIN7](https://attack.mitre.org/groups/G0046) has used WMI to install malware on targeted systems.(Citation: eSentire FIN7 July 2021)", "external_references": [{"description": "eSentire. (2021, July 21). Notorious Cybercrime Gang, FIN7, Lands Malware in Law Firm Using Fake Legal Complaint Against Jack Daniels’ Owner, Brown-Forman Inc.. Retrieved September 20, 2021.", "source_name": "eSentire FIN7 July 2021", "url": "https://www.esentire.com/security-advisories/notorious-cybercrime-gang-fin7-lands-malware-in-law-firm-using-fake-legal-complaint-against-jack-daniels-owner-brown-forman-inc"}], "id": "relationship--3a30af61-b9b4-488e-aebc-dee4dfce52b6", "modified": "2026-07-31T20:48:31.809Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--3753cc21-2dae-4dfb-8481-d004e74502cc", "spec_version": "2.1", "target_ref": "attack-pattern--01a5a209-b94c-450b-b7f9-946497d91055", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9074', 0, 79, '09-mitre-attack', 'retrieved', '3267DE0897F01112CAB5C3313C9331BCCC581D124123AF66B9EDA81D366E0561', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
