VALUES ('doc-09-mitre-attack-p0-9075', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-07-11T18:47:15.630Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FIN7](https://attack.mitre.org/groups/G0046) has loaded a .NET assembly into the currect execution context via `Reflection.Assembly::Load`.(Citation: Gemini_FIN7_Jan2022) ", "external_references": [{"description": "Gemini Advisory. (2022, January 13). FIN7 Uses Flash Drives to Spread Remote Access Trojan. Retrieved May 14, 2025.", "source_name": "Gemini_FIN7_Jan2022", "url": "https://geminiadvisory.io/fin7-flash-drives-spread-remote-access-trojan/"}], "id": "relationship--3c01b9a0-b53f-45f1-a277-f1c0e5d088ed", "modified": "2026-07-31T20:48:31.816Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--3753cc21-2dae-4dfb-8481-d004e74502cc", "spec_version": "2.1", "target_ref": "attack-pattern--4933e63b-9b77-476e-ab29-761bc5b7d15a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9075', 0, 68, '09-mitre-attack', 'retrieved', '73B2B018C7D14C4B46B9E9C39D82B5C74C6B736DB1E437614EF768BFE8AE8DBF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
