VALUES ('doc-09-mitre-attack-p0-9078', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-10-05T17:38:00.017Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FIN7](https://attack.mitre.org/groups/G0046) has utilized the remote management tool Atera to download malware to a compromised system.(Citation: Mandiant FIN7 Apr 2022)", "external_references": [{"description": "Abdo, B., et al. (2022, April 4). FIN7 Power Hour: Adversary Archaeology and the Evolution of FIN7. Retrieved April 5, 2022.", "source_name": "Mandiant FIN7 Apr 2022", "url": "https://www.mandiant.com/resources/evolution-of-fin7"}], "id": "relationship--42684416-c3f0-4668-9c86-77482740179e", "modified": "2026-07-31T20:48:31.846Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--3753cc21-2dae-4dfb-8481-d004e74502cc", "spec_version": "2.1", "target_ref": "attack-pattern--4061e78c-1284-44b4-9116-73e4ac3912f7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9078', 0, 78, '09-mitre-attack', 'retrieved', '65D1B1403CD43192173D627F4D85BEC99C5CC4A2493D7C270459D1A706A29FE3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
