VALUES ('doc-09-mitre-attack-p0-9079', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-07-11T17:46:19.835Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FIN7](https://attack.mitre.org/groups/G0046) has used `attrib +h “C:\\ProgramData\\ssh”` to make the SSH folder hidden.(Citation: BlackBerry_FIN7_April2024) ", "external_references": [{"description": " The BlackBerry Research and Intelligence Team. (2024, April 17). Threat Group FIN7 Targets the U.S. Automotive Industry. Retrieved May 1, 2025.", "source_name": "BlackBerry_FIN7_April2024", "url": "https://blogs.blackberry.com/en/2024/04/fin7-targets-the-united-states-automotive-industry"}], "id": "relationship--42cedca0-2faf-47db-a2da-c81b430ace60", "modified": "2026-07-31T20:48:31.855Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--3753cc21-2dae-4dfb-8481-d004e74502cc", "spec_version": "2.1", "target_ref": "attack-pattern--ec8fc7e2-b356-455c-8db5-2e37be158e7d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9079', 0, 71, '09-mitre-attack', 'retrieved', '8EFD4ED3B6D67F208E4050CCEBCD4F501B22A91F9B12550C84C2879ACF616521', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
