VALUES ('doc-09-mitre-attack-p0-9087', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-27T18:25:48.306Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "FIN7 has used malicious USBs to emulate keystrokes to launch PowerShell to download and execute malware from the adversary''s server.(Citation: FBI Flash FIN7 USB)(Citation: Gemini_FIN7_Jan2022)", "external_references": [{"description": "Gemini Advisory. (2022, January 13). FIN7 Uses Flash Drives to Spread Remote Access Trojan. Retrieved May 14, 2025.", "source_name": "Gemini_FIN7_Jan2022", "url": "https://geminiadvisory.io/fin7-flash-drives-spread-remote-access-trojan/"}, {"description": "The Record. (2022, January 7). FBI: FIN7 hackers target US companies with BadUSB devices to install ransomware. Retrieved January 14, 2022.", "source_name": "FBI Flash FIN7 USB", "url": "https://therecord.media/fbi-fin7-hackers-target-us-companies-with-badusb-devices-to-install-ransomware/"}], "id": "relationship--5c95135f-dbdf-4a9d-8fe0-3a489a171c58", "modified": "2026-07-31T20:48:31.915Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--3753cc21-2dae-4dfb-8481-d004e74502cc", "spec_version": "2.1", "target_ref": "attack-pattern--63e3d25c-d57d-407d-8e6a-2cecd71f90be", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9087', 0, 107, '09-mitre-attack', 'retrieved', 'C91D928EC0C9E44779A5C95E882B76517A78A67EDA9C6020BBAAB86B6C14040A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
