VALUES ('doc-09-mitre-attack-p0-9088', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-23T13:09:35.866Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FIN7](https://attack.mitre.org/groups/G0046) has encrypted virtual disk volumes on ESXi servers using a version of Darkside ransomware.(Citation: CrowdStrike Carbon Spider August 2021)(Citation: Mandiant FIN7 Apr 2022) Additionally, [FIN7](https://attack.mitre.org/groups/G0046) has deployed ransomware as the end payload during big game hunting.(Citation: BlackBerry_FIN7_April2024) ", "external_references": [{"description": " The BlackBerry Research and Intelligence Team. (2024, April 17). Threat Group FIN7 Targets the U.S. Automotive Industry. Retrieved May 1, 2025.", "source_name": "BlackBerry_FIN7_April2024", "url": "https://blogs.blackberry.com/en/2024/04/fin7-targets-the-united-states-automotive-industry"}, {"description": "Abdo, B., et al. (2022, April 4). FIN7 Power Hour: Adversary Archaeology and the Evolution of FIN7. Retrieved April 5, 2022.", "source_name": "Mandiant FIN7 Apr 2022", "url": "https://www.mandiant.com/resources/evolution-of-fin7"}, {"description": "Loui, E. and Reynolds, J. (2021, August 30). CARBON SPIDER Embraces Big Game Hunting, Part 1. Retrieved September 20, 2021.", "source_name": "CrowdStrike Carbon Spider August 2021", "url": "https://www.crowdstrike.com/blog/carbon-spider-embraces-big-game-hunting-part-1/"}], "id": "relationship--5ed383c7-a4b7-441b-8f99-a9927689aea0", "modified": "2026-07-31T20:48:31.923Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--3753cc21-2dae-4dfb-8481-d004e74502cc", "spec_version": "2.1", "target_ref": "attack-pattern--b80d107d-fa0d-4b60-9684-b0433e8bdba0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78c