VALUES ('doc-09-mitre-attack-p0-9105', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-07-11T18:46:56.749Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FIN7](https://attack.mitre.org/groups/G0046) has decoded a malicious PowerShell script using `certutil -decode hex` and has decoded an XOR-obfuscated block of data with the key `qawsed1q2w3e`, which led to the installation of [Lizar](https://attack.mitre.org/software/S0681).(Citation: Gemini_FIN7_Jan2022) ", "external_references": [{"description": "Gemini Advisory. (2022, January 13). FIN7 Uses Flash Drives to Spread Remote Access Trojan. Retrieved May 14, 2025.", "source_name": "Gemini_FIN7_Jan2022", "url": "https://geminiadvisory.io/fin7-flash-drives-spread-remote-access-trojan/"}], "id": "relationship--94f5837a-6e62-4402-ad2e-b7ef7f3c60d9", "modified": "2026-07-31T20:48:32.051Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--3753cc21-2dae-4dfb-8481-d004e74502cc", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9105', 0, 85, '09-mitre-attack', 'retrieved', 'CA0C0C720CEBEFC39B5E82BF72C802FB6DE44026FF325375587E14F39921D434', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
