VALUES ('doc-09-mitre-attack-p0-9110', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-07-11T17:43:28.798Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FIN7](https://attack.mitre.org/groups/G0046) has used the PowerShell script 3CF9.ps1 to perform process discovery by executing `tasklist /v`. Additionally, WsTaskLoad.exe executes `tasklist /v` to perform process discovery.(Citation: BlackBerry_FIN7_April2024) ", "external_references": [{"description": " The BlackBerry Research and Intelligence Team. (2024, April 17). Threat Group FIN7 Targets the U.S. Automotive Industry. Retrieved May 1, 2025.", "source_name": "BlackBerry_FIN7_April2024", "url": "https://blogs.blackberry.com/en/2024/04/fin7-targets-the-united-states-automotive-industry"}], "id": "relationship--9ba9eff2-1471-4395-a2ed-2187aabd893b", "modified": "2026-07-31T20:48:32.089Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--3753cc21-2dae-4dfb-8481-d004e74502cc", "spec_version": "2.1", "target_ref": "attack-pattern--8f4a33ec-8b1f-4b80-a2f6-642b2e479580", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9110', 0, 83, '09-mitre-attack', 'retrieved', '68B458953FEB3B609AEB01F6860C89988B5FDDC3DAB4248143D4964F0E06F700', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
