VALUES ('doc-09-mitre-attack-p0-9114', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-12-04T20:49:19.315Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "(Citation: Microsoft Ransomware as a Service)", "external_references": [{"description": "Microsoft. (2022, May 9). Ransomware as a service: Understanding the cybercrime gig economy and how to protect yourself. Retrieved March 10, 2023.", "source_name": "Microsoft Ransomware as a Service", "url": "https://www.microsoft.com/en-us/security/blog/2022/05/09/ransomware-as-a-service-understanding-the-cybercrime-gig-economy-and-how-to-protect-yourself/"}], "id": "relationship--adfee22f-8471-4e82-b85c-21dcbb93ddde", "modified": "2026-07-31T20:48:32.118Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--3753cc21-2dae-4dfb-8481-d004e74502cc", "spec_version": "2.1", "target_ref": "malware--d9f7383c-95ec-4080-bbce-121c9384457b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9114', 0, 67, '09-mitre-attack', 'retrieved', 'AB50C7061A0DFC313ECA0497ABE4251546B4A69B9C01A488C75FB398483C415B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
