VALUES ('doc-09-mitre-attack-p0-9119', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-07-11T17:42:34.660Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FIN7](https://attack.mitre.org/groups/G0046) has used the PowerShell script 3CF9.ps1 to execute `net time`.(Citation: BlackBerry_FIN7_April2024) ", "external_references": [{"description": " The BlackBerry Research and Intelligence Team. (2024, April 17). Threat Group FIN7 Targets the U.S. Automotive Industry. Retrieved May 1, 2025.", "source_name": "BlackBerry_FIN7_April2024", "url": "https://blogs.blackberry.com/en/2024/04/fin7-targets-the-united-states-automotive-industry"}], "id": "relationship--b846a531-6945-45d6-86f1-7964645d2ef7", "modified": "2026-07-31T20:48:32.156Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--3753cc21-2dae-4dfb-8481-d004e74502cc", "spec_version": "2.1", "target_ref": "attack-pattern--f3c544dc-673c-4ef3-accb-53229f1ae077", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9119', 0, 70, '09-mitre-attack', 'retrieved', 'EE2F9F36C2EF33819E62CA51311C44CABF05CBCA239F05ED0A3952FB24B0D1B9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
