VALUES ('doc-09-mitre-attack-p0-9130', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-10-05T17:03:07.069Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FIN7](https://attack.mitre.org/groups/G0046) has staged legitimate software, that was trojanized to contain an Atera agent installer, on Amazon S3.(Citation: Mandiant FIN7 Apr 2022) [FIN7](https://attack.mitre.org/groups/G0046) has also used an open directory web server as a staging server for payloads and other tools, such as OpenSSH and 7zip.(Citation: Cocomazzi FIN7 Reboot) ", "external_references": [{"description": "Abdo, B., et al. (2022, April 4). FIN7 Power Hour: Adversary Archaeology and the Evolution of FIN7. Retrieved April 5, 2022.", "source_name": "Mandiant FIN7 Apr 2022", "url": "https://www.mandiant.com/resources/evolution-of-fin7"}, {"description": "Cocomazzi, Antonio. (2024, July 17). FIN7 Reboot | Cybercrime Gang Enhances Ops with New EDR Bypasses and Automated Attacks. Retrieved September 24, 2025.", "source_name": "Cocomazzi FIN7 Reboot", "url": "https://www.sentinelone.com/labs/fin7-reboot-cybercrime-gang-enhances-ops-with-new-edr-bypasses-and-automated-attacks/"}], "id": "relationship--d9a18216-bb4f-445a-92a9-abd99ba0609a", "modified": "2026-07-31T20:48:32.239Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--3753cc21-2dae-4dfb-8481-d004e74502cc", "spec_version": "2.1", "target_ref": "attack-pattern--3ee16395-03f0-4690-a32e-69ce9ada0f9e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9130', 0, 137, '09-mitre-attack', 'retrieved', '413E652DA83CE9B6B8FBD03CCD8502294CD92CDCD44E9F79E7F266551018CA7C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": 