VALUES ('doc-09-mitre-attack-p0-9154', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-10T19:35:58.169Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sandworm Team](https://attack.mitre.org/groups/G0034) has exploited vulnerabilities in Microsoft PowerPoint via OLE objects (CVE-2014-4114) and Microsoft Word via crafted TIFF images (CVE-2013-3906).(Citation: iSight Sandworm Oct 2014)(Citation: TrendMicro Sandworm October 2014)(Citation: McAfee Sandworm November 2013)", "external_references": [{"description": "Li, H. (2013, November 5). McAfee Labs Detects Zero-Day Exploit Targeting Microsoft Office. Retrieved June 18, 2020.", "source_name": "McAfee Sandworm November 2013", "url": "https://www.mcafee.com/blogs/other-blogs/mcafee-labs-detects-zero-day-exploit-targeting-microsoft-office-2"}, {"description": "Ward, S.. (2014, October 14). iSIGHT discovers zero-day vulnerability CVE-2014-4114 used in Russian cyber-espionage campaign. Retrieved November 17, 2024.", "source_name": "iSight Sandworm Oct 2014", "url": "https://web.archive.org/web/20160503234007/https:/www.isightpartners.com/2014/10/cve-2014-4114/"}, {"description": "Wu, W. (2014, October 14). An Analysis of Windows Zero-day Vulnerability ‘CVE-2014-4114’ aka “Sandworm”. Retrieved June 18, 2020.", "source_name": "TrendMicro Sandworm October 2014", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/an-analysis-of-windows-zero-day-vulnerability-cve-2014-4114-aka-sandworm/"}], "id": "relationship--2311db5c-218f-44f8-aa50-3e8322b79081", "modified": "2026-07-31T20:48:32.691Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--381fcf73-60f6-4ab2-9991-6af3cbc35192", "spec_version": "2.1", "target_ref": "attack-pattern--be2dcee9-a7a7-4e38-afd6-21b31ecc3d63", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_depre