VALUES ('doc-09-mitre-attack-p0-9181', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-25T15:13:23.470Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[AcidPour](https://attack.mitre.org/software/S1167) is associated with [Sandworm Team](https://attack.mitre.org/groups/G0034).(Citation: SentinelOne AcidPour 2024)", "external_references": [{"description": "Juan Andrés Guerrero-Saade & Tom Hegel. (2024, March 21). AcidPour | New Embedded Wiper Variant of AcidRain Appears in Ukraine. Retrieved November 25, 2024.", "source_name": "SentinelOne AcidPour 2024", "url": "https://www.sentinelone.com/labs/acidpour-new-embedded-wiper-variant-of-acidrain-appears-in-ukraine/"}], "id": "relationship--5a56464c-909d-4d1b-a4ff-3b24aaf45859", "modified": "2026-07-31T20:48:32.925Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--381fcf73-60f6-4ab2-9991-6af3cbc35192", "spec_version": "2.1", "target_ref": "malware--4b1b3a36-bbd6-462c-9c03-7fd4fb5e0dfa", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9181', 0, 70, '09-mitre-attack', 'retrieved', 'FE404F79A79E0C3B9A1EF695C798ACC070B11CA4779FEFC4D74C0A0EC025FA51', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
