VALUES ('doc-09-mitre-attack-p0-9199', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-06T22:42:40.615Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kapeka](https://attack.mitre.org/software/S1190) is associated with [Sandworm Team](https://attack.mitre.org/groups/G0034) operations and previous malware variants such as [GreyEnergy](https://attack.mitre.org/software/S0342).(Citation: Microsoft KnuckleTouch 2024)(Citation: WithSecure Kapeka 2024)", "external_references": [{"description": "Microsoft. (2024, February 14). Backdoor:Win64/KnuckleTouch.A!dha. Retrieved January 6, 2025.", "source_name": "Microsoft KnuckleTouch 2024", "url": "https://www.microsoft.com/en-us/wdsi/threats/malware-encyclopedia-description?Name=Backdoor:Win64/KnuckleTouch.A!dha&threatId=-2147067254"}, {"description": "Mohammad Kazem Hassan Nejad, WithSecure. (2024, April 17). KAPEKA A novel backdoor spotted in Eastern Europe. Retrieved January 6, 2025.", "source_name": "WithSecure Kapeka 2024", "url": "https://labs.withsecure.com/content/dam/labs/docs/WithSecure-Research-Kapeka.pdf"}], "id": "relationship--8b188f9e-96a1-4123-957a-0b2ffe934e35", "modified": "2026-07-31T20:48:33.064Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--381fcf73-60f6-4ab2-9991-6af3cbc35192", "spec_version": "2.1", "target_ref": "malware--a43e55c9-0b7c-42c0-81de-b7a42d724db9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9199', 0, 93, '09-mitre-attack', 'retrieved', 'AFF216609786D44C93CECE8DE3ECC48A5C236063289F2FEB00B63FACC5E4DD99', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
