VALUES ('doc-09-mitre-attack-p0-9200', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-11T16:28:58.231Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sandworm Team](https://attack.mitre.org/groups/G0034) used a backdoor which could execute a supplied DLL using rundll32.exe.(Citation: ESET Telebots July 2017)\t", "external_references": [{"description": "Cherepanov, A.. (2017, July 4). Analysis of TeleBots’ cunning backdoor . Retrieved June 11, 2020.", "source_name": "ESET Telebots July 2017", "url": "https://www.welivesecurity.com/2017/07/04/analysis-of-telebots-cunning-backdoor/"}], "id": "relationship--8e6cbb16-a5cb-4957-8654-dfde2471c3de", "modified": "2026-07-31T20:48:33.071Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--381fcf73-60f6-4ab2-9991-6af3cbc35192", "spec_version": "2.1", "target_ref": "attack-pattern--045d0922-2310-4e60-b5e4-3302302cb3c5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9200', 0, 70, '09-mitre-attack', 'retrieved', '00F97A54058AA105AC8F322E6F704CC7A16A58FCC8F495B7906E2717364A396A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
