VALUES ('doc-09-mitre-attack-p0-9203', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-25T16:28:15.999Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sandworm Team](https://attack.mitre.org/groups/G0034) is linked to [AcidRain](https://attack.mitre.org/software/S1125) deployment during the ViaSat KA-SAT incident in 2022.(Citation: Vincens AcidPour 2024)(Citation: AcidRain JAGS 2022)", "external_references": [{"description": "A.J. Vincens, CyberScoop. (2024, March 18). Researchers spot updated version of malware that hit Viasat. Retrieved March 25, 2024.", "source_name": "Vincens AcidPour 2024", "url": "https://cyberscoop.com/viasat-malware-wiper-acidrain/"}, {"description": "Juan Andres Guerrero-Saade and Max van Amerongen, SentinelOne. (2022, March 31). AcidRain | A Modem Wiper Rains Down on Europe. Retrieved March 25, 2024.", "source_name": "AcidRain JAGS 2022", "url": "https://www.sentinelone.com/labs/acidrain-a-modem-wiper-rains-down-on-europe/"}], "id": "relationship--9411254c-baa7-4e0d-abd2-da6a081add1c", "modified": "2026-07-31T20:48:33.101Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--381fcf73-60f6-4ab2-9991-6af3cbc35192", "spec_version": "2.1", "target_ref": "malware--04cecafd-cb5f-4daf-aa1f-73899116c4a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9203', 0, 107, '09-mitre-attack', 'retrieved', 'ABD4AD359662BFB3AEE736116C312D8ED3FD502D9B9FD33176CCCA035961EFDE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
