VALUES ('doc-09-mitre-attack-p0-9206', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-10T21:56:40.180Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sandworm Team](https://attack.mitre.org/groups/G0034) has used the [BlackEnergy](https://attack.mitre.org/software/S0089) KillDisk component to corrupt the infected system''s master boot record.(Citation: US-CERT Ukraine Feb 2016)(Citation: ESET Telebots June 2017)", "external_references": [{"description": "US-CERT. (2016, February 25). ICS Alert (IR-ALERT-H-16-056-01) Cyber-Attack Against Ukrainian Critical Infrastructure. Retrieved June 10, 2020.", "source_name": "US-CERT Ukraine Feb 2016", "url": "https://www.us-cert.gov/ics/alerts/IR-ALERT-H-16-056-01"}, {"description": "Cherepanov, A.. (2017, June 30). TeleBots are back: Supply chain attacks against Ukraine. Retrieved June 11, 2020.", "source_name": "ESET Telebots June 2017", "url": "https://www.welivesecurity.com/2017/06/30/telebots-back-supply-chain-attacks-against-ukraine/"}], "id": "relationship--98b6dbac-dac9-4856-9b67-25c49e20448e", "modified": "2026-07-31T20:48:33.123Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--381fcf73-60f6-4ab2-9991-6af3cbc35192", "spec_version": "2.1", "target_ref": "attack-pattern--0af0ca99-357d-4ba1-805f-674fdfb7bef9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9206', 0, 103, '09-mitre-attack', 'retrieved', '58F1589E9D024E63668ED210605868A57FCA48E01DDC8D4041400DBFD582B97B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
