VALUES ('doc-09-mitre-attack-p0-9208', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-04T21:30:14.830Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "(Citation: Dragos Crashoverride 2018)(Citation: Dragos Crashoverride 2017)(Citation: ESET Industroyer)(Citation: Secureworks IRON VIKING)(Citation: mandiant_apt44_unearthing_sandworm)", "external_references": [{"description": "Anton Cherepanov. (2017, June 12). Win32/Industroyer: A new threat for industrial controls systems. Retrieved December 18, 2020.", "source_name": "ESET Industroyer", "url": "https://www.welivesecurity.com/wp-content/uploads/2017/06/Win32_Industroyer.pdf"}, {"description": "Dragos Inc.. (2017, June 13). CRASHOVERRIDE Analysis of the Threat to Electric Grid Operations. Retrieved December 18, 2020.", "source_name": "Dragos Crashoverride 2017", "url": "https://dragos.com/blog/crashoverride/CrashOverride-01.pdf"}, {"description": "Joe Slowik. (2018, October 12). Anatomy of an Attack: Detecting and Defeating CRASHOVERRIDE. Retrieved December 18, 2020.", "source_name": "Dragos Crashoverride 2018", "url": "https://www.dragos.com/wp-content/uploads/CRASHOVERRIDE2018.pdf"}, {"description": "Roncone, G. et al. (n.d.). APT44: Unearthing Sandworm. Retrieved July 11, 2024.", "source_name": "mandiant_apt44_unearthing_sandworm", "url": "https://services.google.com/fh/files/misc/apt44-unearthing-sandworm.pdf"}, {"description": "Secureworks. (2020, May 1). IRON VIKING Threat Profile. Retrieved June 10, 2020.", "source_name": "Secureworks IRON VIKING", "url": "https://www.secureworks.com/research/threat-profiles/iron-viking"}], "id": "relationship--9f07c92a-78a0-438a-8cb2-01e2bddaeb42", "modified": "2026-07-31T20:48:33.138Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--381fcf73-60f6-4ab2-9991-6af3cbc35192", "spec_version": "2.1", "target_ref"