VALUES ('doc-09-mitre-attack-p0-9212', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-01T18:59:55.331Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sandworm Team](https://attack.mitre.org/groups/G0034) used various third-party email campaign management services to deliver phishing emails.(Citation: Leonard TAG 2023)", "external_references": [{"description": "Billy Leonard. (2023, April 19). Ukraine remains Russia’s biggest cyber focus in 2023. Retrieved March 1, 2024.", "source_name": "Leonard TAG 2023", "url": "https://blog.google/threat-analysis-group/ukraine-remains-russias-biggest-cyber-focus-in-2023/"}], "id": "relationship--a4676ad1-f8d2-43f0-a342-8d5d01bff9cf", "modified": "2026-07-31T20:48:33.167Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--381fcf73-60f6-4ab2-9991-6af3cbc35192", "spec_version": "2.1", "target_ref": "attack-pattern--0458aab9-ad42-4eac-9e22-706a95bafee2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9212', 0, 70, '09-mitre-attack', 'retrieved', '21A49863FD20A42F06BB89DEDBCF24000C5CC3511069AD023CD81BBFDFF46977', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
