VALUES ('doc-09-mitre-attack-p0-9213', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-10T21:56:40.261Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sandworm Team](https://attack.mitre.org/groups/G0034) has used remote administration tools or remote industrial control system client software for execution and to maliciously release electricity breakers.(Citation: US-CERT Ukraine Feb 2016)(Citation: Microsoft Prestige ransomware October 2022)", "external_references": [{"description": "MSTIC. (2022, October 14). New “Prestige” ransomware impacts organizations in Ukraine and Poland. Retrieved January 19, 2023.", "source_name": "Microsoft Prestige ransomware October 2022", "url": "https://www.microsoft.com/en-us/security/blog/2022/10/14/new-prestige-ransomware-impacts-organizations-in-ukraine-and-poland/"}, {"description": "US-CERT. (2016, February 25). ICS Alert (IR-ALERT-H-16-056-01) Cyber-Attack Against Ukrainian Critical Infrastructure. Retrieved June 10, 2020.", "source_name": "US-CERT Ukraine Feb 2016", "url": "https://www.us-cert.gov/ics/alerts/IR-ALERT-H-16-056-01"}], "id": "relationship--ad949bd4-7ffd-4712-91d8-4a8523db6b50", "modified": "2026-07-31T20:48:33.183Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--381fcf73-60f6-4ab2-9991-6af3cbc35192", "spec_version": "2.1", "target_ref": "attack-pattern--4061e78c-1284-44b4-9116-73e4ac3912f7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9213', 0, 111, '09-mitre-attack', 'retrieved', 'A7A7D6DBF172FCEA55EB83ABB3462F08FB0E18BD55C91DCC9E961EACEF3BD233', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
