VALUES ('doc-09-mitre-attack-p0-9217', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-20T18:28:13.118Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sandworm Team](https://attack.mitre.org/groups/G0034) has used multiple publicly available tools during operations, such as Cobalt Strike.(Citation: mandiant_apt44_unearthing_sandworm)", "external_references": [{"description": "Roncone, G. et al. (n.d.). APT44: Unearthing Sandworm. Retrieved July 11, 2024.", "source_name": "mandiant_apt44_unearthing_sandworm", "url": "https://services.google.com/fh/files/misc/apt44-unearthing-sandworm.pdf"}], "id": "relationship--bfa683a7-3c94-4de9-966c-2c06cfdf5a78", "modified": "2026-07-31T20:48:33.212Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--381fcf73-60f6-4ab2-9991-6af3cbc35192", "spec_version": "2.1", "target_ref": "malware--a7881f21-e978-4fe4-af56-92c9416a2616", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9217', 0, 62, '09-mitre-attack', 'retrieved', '8429DCA054566F4EFC78567184B4C8C40346E287E7A3DFBE04FF2126CB26D220', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
