VALUES ('doc-09-mitre-attack-p0-9222', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-10T18:36:54.638Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "(Citation: NCSC Sandworm Feb 2020)(Citation: US District Court Indictment GRU Unit 74455 October 2020)(Citation: UK NCSC Olympic Attacks October 2020)(Citation: Secureworks IRON VIKING )(Citation: Trend Micro Cyclops Blink March 2022)(Citation: mandiant_apt44_unearthing_sandworm)", "external_references": [{"description": "Haquebord, F. et al. (2022, March 17). Cyclops Blink Sets Sights on Asus Routers. Retrieved March 17, 2022.", "source_name": "Trend Micro Cyclops Blink March 2022", "url": "https://www.trendmicro.com/en_us/research/22/c/cyclops-blink-sets-sights-on-asus-routers--.html"}, {"description": "NCSC. (2020, February 20). NCSC supports US advisory regarding GRU intrusion set Sandworm. Retrieved June 10, 2020.", "source_name": "NCSC Sandworm Feb 2020", "url": "https://www.ncsc.gov.uk/news/ncsc-supports-sandworm-advisory"}, {"description": "Roncone, G. et al. (n.d.). APT44: Unearthing Sandworm. Retrieved July 11, 2024.", "source_name": "mandiant_apt44_unearthing_sandworm", "url": "https://services.google.com/fh/files/misc/apt44-unearthing-sandworm.pdf"}, {"description": "Scott W. Brady. (2020, October 15). United States vs. Yuriy Sergeyevich Andrienko et al.. Retrieved November 25, 2020.", "source_name": "US District Court Indictment GRU Unit 74455 October 2020", "url": "https://www.justice.gov/opa/press-release/file/1328521/download"}, {"description": "Secureworks. (2020, May 1). IRON VIKING Threat Profile. Retrieved June 10, 2020.", "source_name": "Secureworks IRON VIKING ", "url": "https://www.secureworks.com/research/threat-profiles/iron-viking"}, {"description": "UK NCSC. (2020, October 19). UK exposes series of Russian cyber attacks against Olympic and Paralympic Games . Retrieved November 30, 2020.", "source_name": "UK NCSC Olympic Attacks October