VALUES ('doc-09-mitre-attack-p0-9224', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-11-25T21:00:55.751Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sandworm Team](https://attack.mitre.org/groups/G0034) has created email accounts that mimic legitimate organizations for its spearphishing operations.(Citation: US District Court Indictment GRU Unit 74455 October 2020)", "external_references": [{"description": "Scott W. Brady. (2020, October 15). United States vs. Yuriy Sergeyevich Andrienko et al.. Retrieved November 25, 2020.", "source_name": "US District Court Indictment GRU Unit 74455 October 2020", "url": "https://www.justice.gov/opa/press-release/file/1328521/download"}], "id": "relationship--d3ac0edb-8e56-440f-a844-be61b6045901", "modified": "2026-07-31T20:48:33.286Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--381fcf73-60f6-4ab2-9991-6af3cbc35192", "spec_version": "2.1", "target_ref": "attack-pattern--65013dd2-bc61-43e3-afb5-a14c4fa7437a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9224', 0, 84, '09-mitre-attack', 'retrieved', '053DAE73B359498DC65B856F0EAF772C2037DBEB02F941510D7E17B58BAA5A37', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
