VALUES ('doc-09-mitre-attack-p0-9351', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-14T20:01:40.269Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mustang Panda](https://attack.mitre.org/groups/G0129) has the ability to decrypt its payload prior to execution.(Citation: Lab52 MUSTANG PANDA PUBLOAD MAY 2023)(Citation: EclecticIQ Mustang Panda PlugX)(Citation: Palo Alto Networks, Unit 42)(Citation: Sophos Mustang Panda PLUGX) [Mustang Panda](https://attack.mitre.org/groups/G0129) has also utilized RC4 encryption for malicious payloads.(Citation: Google Threat Intelligence Group MUSTANG PANDA PLUGX August 2025)(Citation: Unit42 Bookworm Nov2015)", "external_references": [{"description": "Dex. (n.d.). New Mustang Panda’s campaing against Australia. Retrieved August 4, 2025.", "source_name": "Lab52 MUSTANG PANDA PUBLOAD MAY 2023", "url": "https://lab52.io/blog/new-mustang-pandas-campaing-against-australia/"}, {"description": "EclecticIQ Threat Research Team. (2023, February 2). Mustang Panda APT Group Uses European Commission-Themed Lure to Deliver PlugX Malware. Retrieved September 9, 2025.", "source_name": "EclecticIQ Mustang Panda PlugX", "url": "https://blog.eclecticiq.com/mustang-panda-apt-group-uses-european-commission-themed-lure-to-deliver-plugx-malware"}, {"description": "Patrick Whitsell. (2025, August 25). Deception in Depth: PRC-Nexus Espionage Campaign Hijacks Web Traffic to Target Diplomats. Retrieved September 9, 2025.", "source_name": "Google Threat Intelligence Group MUSTANG PANDA PLUGX August 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/prc-nexus-espionage-targets-diplomats"}, {"description": "Robert Falcone, Mike Scott, Juan Cortes. (2015, November 10). Bookworm Trojan: A Model of Modular Architecture. Retrieved July 21, 2025.", "source_name": "Unit42 Bookworm Nov2015", "url": "https://unit42.paloaltonetworks.com/bookworm-trojan-a-model-of-modular-architecture/"}, {