VALUES ('doc-09-mitre-attack-p0-9352', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-13T20:27:51.993Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mustang Panda](https://attack.mitre.org/groups/G0129) has used netstat -ano to determine network connection information.(Citation: Avira Mustang Panda January 2020)", "external_references": [{"description": "Hamzeloofard, S. (2020, January 31). New wave of PlugX targets Hong Kong | Avira Blog. Retrieved April 13, 2021.", "source_name": "Avira Mustang Panda January 2020", "url": "https://www.avira.com/en/blog/new-wave-of-plugx-targets-hong-kong"}], "id": "relationship--2cc2c5ca-7c7a-4ab7-9cb3-76bdd14324b8", "modified": "2026-07-31T18:47:51.819Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--420ac20b-f2b9-42b8-aa1a-6d4b72895ca4", "spec_version": "2.1", "target_ref": "attack-pattern--7e150503-88e7-4861-866b-ff1ac82c4475", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9352', 0, 74, '09-mitre-attack', 'retrieved', '2F01A7E7576448C69F05476658334BFF896948536FF26A76DF2E844016E48814', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
