VALUES ('doc-09-mitre-attack-p0-9354', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-14T20:44:10.032Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mustang Panda](https://attack.mitre.org/groups/G0129) has utilized an established Github account to create a tunnel within the victim environment using Visual Studio Code through the `code.exe tunnel` command.(Citation: Unit42 Chinese VSCode 06 September 2024)", "external_references": [{"description": "Tom Fakterman. (2024, September 6). Chinese APT Abuses VSCode to Target Government in Asia. Retrieved March 24, 2025.", "source_name": "Unit42 Chinese VSCode 06 September 2024", "url": "https://unit42.paloaltonetworks.com/stately-taurus-abuses-vscode-southeast-asian-espionage/"}], "id": "relationship--2f405cde-1625-423a-a4d4-cde1387e6481", "modified": "2026-07-31T18:47:51.854Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--420ac20b-f2b9-42b8-aa1a-6d4b72895ca4", "spec_version": "2.1", "target_ref": "attack-pattern--77e29a47-e263-4f11-8692-e5012f44dbac", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9354', 0, 89, '09-mitre-attack', 'retrieved', '807B2BE40611D46D3F8C56C10660D903BEF54DB9C9D2AA7A5FF62130F640C49E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
