VALUES ('doc-09-mitre-attack-p0-9355', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-15T13:44:32.681Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mustang Panda](https://attack.mitre.org/groups/G0129) has also exfiltrated archived files to cloud services such as Dropbox using `curl`.(Citation: Palo Alto Unit42 STATELY TAURUS TONESHELL September 2023)(Citation: Unit42 Chinese VSCode 06 September 2024)", "external_references": [{"description": "Lior Rochberger, Tom Fakterman, Robert Falcone. (2023, September 22). Cyberespionage Attacks Against Southeast Asian Government Linked to Stately Taurus, Aka Mustang Panda. Retrieved September 9, 2025.", "source_name": "Palo Alto Unit42 STATELY TAURUS TONESHELL September 2023", "url": "https://unit42.paloaltonetworks.com/stately-taurus-attacks-se-asian-government/"}, {"description": "Tom Fakterman. (2024, September 6). Chinese APT Abuses VSCode to Target Government in Asia. Retrieved March 24, 2025.", "source_name": "Unit42 Chinese VSCode 06 September 2024", "url": "https://unit42.paloaltonetworks.com/stately-taurus-abuses-vscode-southeast-asian-espionage/"}], "id": "relationship--2f8d04f9-04af-4bf9-9841-2d7728abdf84", "modified": "2026-07-31T18:47:51.871Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--420ac20b-f2b9-42b8-aa1a-6d4b72895ca4", "spec_version": "2.1", "target_ref": "attack-pattern--bf1b6176-597c-4600-bfcd-ac989670f96b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9355', 0, 125, '09-mitre-attack', 'retrieved', 'BD2E7E3C2E5221639EA2BF268A93E5332C1140414E82E24501ADE29BE0633451', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "