VALUES ('doc-09-mitre-attack-p0-9373', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-14T20:55:32.593Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mustang Panda](https://attack.mitre.org/groups/G0129) has queried Active Directory for computers using [AdFind](https://attack.mitre.org/software/S0552).(Citation: Palo Alto Unit42 STATELY TAURUS TONESHELL September 2023) [Mustang Panda](https://attack.mitre.org/groups/G0129) has also utilized SharpNBTScan to scan the victim environment.(Citation: Unit42 Chinese VSCode 06 September 2024)", "external_references": [{"description": "Lior Rochberger, Tom Fakterman, Robert Falcone. (2023, September 22). Cyberespionage Attacks Against Southeast Asian Government Linked to Stately Taurus, Aka Mustang Panda. Retrieved September 9, 2025.", "source_name": "Palo Alto Unit42 STATELY TAURUS TONESHELL September 2023", "url": "https://unit42.paloaltonetworks.com/stately-taurus-attacks-se-asian-government/"}, {"description": "Tom Fakterman. (2024, September 6). Chinese APT Abuses VSCode to Target Government in Asia. Retrieved March 24, 2025.", "source_name": "Unit42 Chinese VSCode 06 September 2024", "url": "https://unit42.paloaltonetworks.com/stately-taurus-abuses-vscode-southeast-asian-espionage/"}], "id": "relationship--4f31fe80-6994-443d-ad54-7584601618dd", "modified": "2026-07-31T18:47:52.275Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--420ac20b-f2b9-42b8-aa1a-6d4b72895ca4", "spec_version": "2.1", "target_ref": "attack-pattern--e358d692-23c0-4a31-9eb6-ecc13a8d7735", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9373', 0, 131, '09-mitre-attack', 'retrieved', '53AD994BF4EA13A7028288B780AFAD6DAF0B69E23EDA818