VALUES ('doc-09-mitre-attack-p0-9375', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-15T14:13:43.173Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mustang Panda](https://attack.mitre.org/groups/G0129) has utilized TLS record headers in network packets to impersonate various versions of TLS protocols to blend in with legitimate network traffic. [Mustang Panda](https://attack.mitre.org/groups/G0129) has used FakeTLS to communicate with its C2 servers.(Citation: Zscaler)", "external_references": [{"description": "Sudeep Singh. (2025, April 16). Latest Mustang Panda Arsenal: ToneShell and StarProxy | P1. Retrieved July 21, 2025.", "source_name": "Zscaler", "url": "https://www.zscaler.com/blogs/security-research/latest-mustang-panda-arsenal-toneshell-and-starproxy-p1"}], "id": "relationship--5025e4e1-4862-430c-a5fd-8ca7fece809b", "modified": "2026-07-31T18:47:52.318Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--420ac20b-f2b9-42b8-aa1a-6d4b72895ca4", "spec_version": "2.1", "target_ref": "attack-pattern--c325b232-d5bc-4dde-a3ec-71f3db9e8adc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9375', 0, 89, '09-mitre-attack', 'retrieved', 'EED778785355B58E1682F1204D2335E6DAD547BD672ED03FF9055987F732C1D1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
