VALUES ('doc-09-mitre-attack-p0-9380', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-14T21:14:45.374Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mustang Panda](https://attack.mitre.org/groups/G0129) has leveraged legitimate software tools such as AntiVirus Agents, Security Services, and App Development tools to execute scripts and to side-load dlls.(Citation: Palo Alto Unit42 STATELY TAURUS TONESHELL September 2023)(Citation: Trend Micro Mustang Panda Earth Preta Toneshell February 2025)", "external_references": [{"description": "Lior Rochberger, Tom Fakterman, Robert Falcone. (2023, September 22). Cyberespionage Attacks Against Southeast Asian Government Linked to Stately Taurus, Aka Mustang Panda. Retrieved September 9, 2025.", "source_name": "Palo Alto Unit42 STATELY TAURUS TONESHELL September 2023", "url": "https://unit42.paloaltonetworks.com/stately-taurus-attacks-se-asian-government/"}, {"description": "Nathaniel Morales, Nick Dai. (2025, February 18). Earth Preta Mixes Legitimate and Malicious Components to Sidestep Detection. Retrieved September 10, 2025.", "source_name": "Trend Micro Mustang Panda Earth Preta Toneshell February 2025", "url": "https://www.trendmicro.com/en_us/research/25/b/earth-preta-mixes-legitimate-and-malicious-components-to-sidestep-detection.html"}], "id": "relationship--58aa294e-c14c-45f8-80e6-9b05229cbb0f", "modified": "2026-07-31T18:47:52.401Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--420ac20b-f2b9-42b8-aa1a-6d4b72895ca4", "spec_version": "2.1", "target_ref": "attack-pattern--92a78814-b191-47ca-909c-1ccfe3777414", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9380', 0, 143, '09-mitre-attack', 'retrieved', '513BEA4FDA982FEF0AC2E75EFBC11D209978313001D52E6760AB78A8E62C803C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
