VALUES ('doc-09-mitre-attack-p0-9383', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-14T21:05:41.194Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mustang Panda](https://attack.mitre.org/groups/G0129) leveraged [Impacket](https://attack.mitre.org/software/S0357) to gather information about the network, discover devices, users and query directories on remote machines to identify files to exfiltrate.(Citation: Palo Alto Unit42 STATELY TAURUS TONESHELL September 2023)", "external_references": [{"description": "Lior Rochberger, Tom Fakterman, Robert Falcone. (2023, September 22). Cyberespionage Attacks Against Southeast Asian Government Linked to Stately Taurus, Aka Mustang Panda. Retrieved September 9, 2025.", "source_name": "Palo Alto Unit42 STATELY TAURUS TONESHELL September 2023", "url": "https://unit42.paloaltonetworks.com/stately-taurus-attacks-se-asian-government/"}], "id": "relationship--640596c4-55d0-4d7d-a734-b4cfb864c9f5", "modified": "2026-07-31T18:47:52.462Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--420ac20b-f2b9-42b8-aa1a-6d4b72895ca4", "spec_version": "2.1", "target_ref": "tool--26c87906-d750-42c5-946c-d4162c73fc7b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9383', 0, 100, '09-mitre-attack', 'retrieved', '7F2CF7FF2C4703E9FC1A39E3D85D73BB6865C01995BA3C693DC1FAEDEBF16D3D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
