VALUES ('doc-09-mitre-attack-p0-9435', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-12T19:26:30.386Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mustang Panda](https://attack.mitre.org/groups/G0129) has sent malicious files requiring direct victim interaction to execute.(Citation: Anomali MUSTANG PANDA October 2019)(Citation: CSIRT CTI MUSTANG PANDA PUBLOAD TONESHELL JAN 2024)(Citation: IBM MUSTANG PANDA PUBLOAD CLAIMLOADER JUNE 2025)(Citation: 2025_IBM_PUBLOAD_TONESHELL_HIUPAN_CLAIMLOADER_MUSTANG PANDA)(Citation: Avira Mustang Panda January 2020)(Citation: Google TAG Ukraine Threat Landscape March 2022)(Citation: Recorded Future REDDELTA July 2020)(Citation: Crowdstrike MUSTANG PANDA June 2018)(Citation: Proofpoint TA416 Europe March 2022)(Citation: Zscaler PAKLOG CorkLog SplatCloak Splatdropper April 2025) [Mustang Panda](https://attack.mitre.org/groups/G0129) has also leveraged executable files that display decoy documents to the victim to provide a resemblance of legitimacy with customized themes related to the victim.(Citation: Eset PlugX Korplug Mustang Panda March 2022)(Citation: Cisco Talos MUSTANG PANDA PLUGX PUBLOAD MAY 2022)(Citation: Lab52 MUSTANG PANDA PUBLOAD MAY 2023)(Citation: EclecticIQ Mustang Panda PlugX)(Citation: Trend Micro MUSTANG PANDA PUBLOAD HIUPAN SEPTEMBER 2024)(Citation: Trend Micro Mustang Panda Earth Preta Toneshell February 2025)(Citation: 2022 November_TrendMicro_Earth Preta_Toneshell_Pubload)(Citation: Unit42 Bookworm Nov2015)(Citation: Palo Alto Networks, Unit 42)(Citation: Sophos PlugX September 2022)(Citation: Sophos Mustang Panda PLUGX)", "external_references": [{"description": "Alexandre Cote Cyr. (2022, March 23). Mustang Panda’s Hodur: Old tricks, new Korplug variant. Retrieved September 9, 2025.", "source_name": "Eset PlugX Korplug Mustang Panda March 2022", "url": "https://www.welivesecurity.com/2022/03/23/mustang-panda-hodur-old-tricks-new-korplug-variant/"}, {"description": "Anomali Threat Research. (2019, October 7). China-Based APT Mustang Panda Targets Minority Groups, Public and Private Sector Organizations. Retrieved April 12, 2021.", "source_name": "Anomali MUSTANG PANDA October 2019", "url": "https://www.anomali.com/blog/china-based-apt-mustang-panda-targets-minority-groups-public-and-private-sector-organizations"}, {"description": "Asheer Malhotra, Jungsoo An, Kendall Mc. (2022, May 5). Mustang Panda deploys a new wave of malware targeting Europe. Retrieved August 4, 2025.", "source_name": "Cisco Talos MUSTANG PANDA PLUGX PUBLOAD MAY 2022", "url": "https://blog.talosintelligence.com/mustang-panda-targets-europe/"}, {"description": "CSIRT CTI. (2024, January 23). Stately Taurus Targets Myanmar Amidst Concerns over Military Junta’s Handling of Rebel Attacks. Retrieved August 4, 2025.", "source_name": "CSIRT CTI MUSTANG PANDA PUBLOAD TONESHELL JAN 2024", "url": "https://csirt-cti.net/2024/01/23/stately-taurus-targets-myanmar/"}, {"description": "Dex. (n.d.). New Mustang Panda’s campaing against Australia. Retrieved August 4, 2025.", "source_name": "Lab52 MUSTANG PANDA PUBLOAD MAY 2023", "url": "https://lab52.io/blog/new-mustang-pandas-campaing-against-australia/"}, {"description": "EclecticIQ Threat Research Team. (2023, February 2). Mustang Panda APT Group Uses European Commission-Themed Lure to Deliver PlugX Malware. Retrieved September 9, 2025.", "source_name": "EclecticIQ Mustang Panda PlugX", "url": "https://blog.eclecticiq.com/mustang-panda-apt-group-uses-european-commission-themed-lure-to-deliver-plugx-malware"}, {"description": "Golo Muhr, Joshua Chung. (2025, June 23). Hive0154 aka Mustang Panda shifts focus on Tibetan community to deploy Pubload backdoor. Retrieved August 4, 2025.", "source_name": "IBM MUSTANG PANDA PUBLOAD CLAIMLOADER JUNE 2025", "url": "https://www.ibm.com/think/x-force/hive0154-mustang-panda-shifts-focus-tibetan-community-deploy-pubload-backdoor"}, {"description": "Golo Muhr, Joshua Chung. (2025, May 15). Hive0154 targeting US, Philippines, Pakistan and Taiwan in suspected espionage campaign. Retrieved August 4, 2025.", "source_name": "2025_IBM_PUBLOAD_TONESHELL_HIUPAN_CLAIMLOADER_MUSTANG PANDA", "url": "https://www.ibm.com/think/x-force/hive0154-targeting-us-philippines-pakistan-taiwan"}, {"description": "Hamzeloofard, S. (2020, January 31). New wave of PlugX targets Hong Kong | Avira Blog. Retrieved April 13, 2021.", "source_name": "Avira Mustang Panda January 2020", "url": "https://www.avira.com/en/blog/new-wave-of-plugx-targets-hong-kong"}, {"description": "Huntley, S. (2022, March 7). An update on the threat landscape. Retrieved March 16, 2022.", "source_name": "Google TAG Ukraine Threat Landscape March 2022", "url": "https://blog.google/threat-analysis-group/update-threat-landscape-ukraine"}, {"description": "Insikt Group. (2020, July 28). CHINESE STATE-SPONSORED GROUP ‘REDDELTA’ TARGETS THE VATICAN AND CATHOLIC ORGANIZATIONS. Retrieved April 13, 2021.", "source_name": "Recorded Future REDDELTA July 2020", "url": "https://go.recordedfuture.com/hubfs/reports/cta-2020-0728.pdf"}, {"description": "Lenart Bermejo, Sunny Lu, Ted Lee. (2024, September 9). Earth Preta Evolves its Attacks with New Malware and Strategies. Retrieved August 4, 2025.", "source_name": "Trend Micro MUSTANG PANDA PUBLOAD HIUPAN SEPTEMBER 2024", "url": "https://www.trendmicro.com/en_us/research/24/i/earth-preta-new-malware-and-strategies.html"}, {"description": "Meyers, A. (2018, June 15). Meet CrowdStrike’s Adversary of the Month for June: MUSTANG PANDA. Retrieved April 12, 2021.", "source_name": "Crowdstrike MUSTANG PANDA June 2018", "url": "https://www.crowdstrike.com/blog/meet-crowdstrikes-adversary-of-the-month-for-june-mustang-panda/"}, {"description": "Nathaniel Morales, Nick Dai. (2025, February 18). Earth Preta Mixes Legitimate and Malicious Components to Sidestep Detection. Retrieved September 10, 2025.", "source_name": "Trend Micro Mustang Panda Earth Preta Toneshell February 2025", "url": "https://www.trendmicro.com/en_us/research/25/b/earth-preta-mixes-legitimate-and-malicious-components-to-sidestep-detection.html"}, {"description": "Nick Dai, Vickie Su, Sunny Lu. (2022, November 18). Earth Preta Spear-Phishing Governments Worldwide. Retrieved August 4, 2025.", "source_name": "2022 November_TrendMicro_Earth Preta_Toneshell_Pubload", "url": "https://www.trendmicro.com/en_us/research/22/k/earth-preta-spear-phishing-governments-worldwide.html"}, {"description": "Raggi, M. et al. (2022, March 7). The Good, the Bad, and the Web Bug: TA416 Increases Operational Tempo Against European Governments as Conflict in Ukraine Escalates. Retrieved March 16, 2022.", "source_name": "Proofpoint TA416 Europe March 2022", "url": "https://www.proofpoint.com/us/blog/threat-insight/good-bad-and-web-bug-ta416-increases-operational-tempo-against-european"}, {"description": "Robert Falcone, Mike Scott, Juan Cortes. (2015, November 10). Bookworm Trojan: A Model of Modular Architecture. Retrieved July 21, 2025.", "source_name": "Unit42 Bookworm Nov2015", "url": "https://unit42.paloaltonetworks.com/bookworm-trojan-a-model-of-modular-architecture/"}, {"description": "Robert Falcone. (2025, February 20). Stately Taurus Activity in Southeast Asia Links to Bookworm Malware. Retrieved July 21, 2025.", "source_name": "Palo Alto Networks, Unit 42", "url": "https://unit42.paloaltonetworks.com/stately-taurus-uses-bookworm-malware/"}, {"description": "Secureworks Counter Threat Unit Research Team. (2022, April 27). BRONZE PRESIDENT Targets Russian Speakers with Updated PlugX. Retrieved September 9, 2025.", "source_name": "Sophos PlugX September 2022", "url": "https://www.secureworks.com/blog/bronze-president-targets-russian-speakers-with-updated-plugx"}, {"description": "Secureworks Counter Threat Unit Research Team. (2022, September 8). BRONZE PRESIDENT Targets Government Officials. Retrieved September 9, 2025.", "source_name": "Sophos Mustang Panda PLUGX", "url": "https://www.secureworks.com/blog/bronze-president-targets-government-officials"}, {"description": "Sudeep Singh. (2025, April 16). Latest Mustang Panda Arsenal: PAKLOG, CorKLOG, and SplatCloak | P2. Retrieved September 12, 2025.", "source_name": "Zscaler PAKLOG CorkLog SplatCloak Splatdropper April 2025", "url": "https://www.zscaler.com/blogs/security-research/latest-mustang-panda-arsenal-paklog-corklog-and-splatcloak-p2"}], "id": "relationship--e122c13d-078d-4404-b2a0-e0e2341dbd2e", "modified": "2026-07-31T18:47:53.578Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--420ac20b-f2b9-42b8-aa1a-6d4b72895ca4", "spec_version": "2.1", "target_ref": "attack-pattern--232b7f21-adf9-4b42-b936-b9d6f7df856e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9435', 0, 815, '09-mitre-attack', 'retrieved', 'C44D9E262681B56743CD5B0E691837EFB7B51EEDA740FD606C2B62526825449F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
